// app_V25.zig
// JAIDE V25 - Jade MetaRuntime Polyglot System
const std = @import("std");
const print = std.debug.print;
const JadeCore = @import("jade/core.zig");
const SynapseTokenizer = @import("tokenizer/synapse.zig");
const AethelredPipeline = @import("pipeline/aethelred.zig");
const NimScheduler = @import("scheduler/nim_scheduler.nim");

pub const JAIDEV25System = struct {
    allocator: std.mem.Allocator,
    core: JadeCore.JadeSSM,
    tokenizer: SynapseTokenizer.SynapseTokenizer,
    pipeline: AethelredPipeline.Pipeline,
    is_initialized: bool,

    const Self = @This();

    pub fn init(allocator: std.mem.Allocator) !*Self {
        var system = try allocator.create(Self);
        system.* = Self{
            .allocator = allocator,
            .core = undefined,
            .tokenizer = undefined,
            .pipeline = undefined,
            .is_initialized = false,
        };

        system.core = try JadeCore.JadeSSM.init(allocator, 8192, 256, 2048);
        system.tokenizer = try SynapseTokenizer.SynapseTokenizer.init(allocator);
        system.pipeline = try AethelredPipeline.Pipeline.init(allocator);
        system.is_initialized = true;

        return system;
    }

    pub fn deinit(self: *Self) void {
        if (self.is_initialized) {
            self.core.deinit();
            self.tokenizer.deinit();
            self.pipeline.deinit();
        }
        self.allocator.destroy(self);
    }

    pub fn runInference(self: *Self, prompt: []const u8, response_ptr: *[*:0]u8) i32 {
        const tokens = self.tokenizer.encode(prompt) catch return -1;
        defer self.allocator.free(tokens);

        const output_tokens = self.core.forward(tokens) catch return -2;
        defer self.allocator.free(output_tokens);

        const response_text = self.tokenizer.decode(output_tokens) catch return -3;
        response_ptr.* = @ptrCast(response_text.ptr);
        return 0;
    }

    pub fn runDistributedTraining(self: *Self, dataset_path: [*:0]const u8) bool {
        const path = std.mem.span(dataset_path);
        return self.pipeline.processDataset(path) catch false;
    }
};

export fn jaide_v25_system_create() ?*JAIDEV25System {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    const allocator = gpa.allocator();
    return JAIDEV25System.init(allocator) catch null;
}

export fn jaide_v25_system_destroy(system: *JAIDEV25System) void {
    system.deinit();
}

export fn jaide_v25_run_inference(system: *JAIDEV25System, prompt: [*:0]const u8, response: *[*:0]u8) i32 {
    const prompt_slice = std.mem.span(prompt);
    return system.runInference(prompt_slice, response);
}

export fn jaide_v25_run_distributed_training(system: *JAIDEV25System, dataset_path: [*:0]const u8) bool {
    return system.runDistributedTraining(dataset_path);
}

export fn jaide_v25_free_string(str: [*:0]u8) void {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    const allocator = gpa.allocator();
    allocator.free(std.mem.span(str));
}

// jade/core.zig
const std = @import("std");
const math = std.math;

pub const JadeSSM = struct {
    allocator: std.mem.Allocator,
    d_model: u32,
    d_state: u32,
    seq_len: u32,
    A_matrix: []f32,
    B_matrix: []f32,
    C_matrix: []f32,
    D_matrix: []f32,
    delta_proj: []f32,
    hidden_state: []f32,
    output_buffer: []f32,

    const Self = @This();

    pub fn init(allocator: std.mem.Allocator, d_model: u32, d_state: u32, seq_len: u32) !Self {
        const a_size = d_model * d_state;
        const b_size = d_model * d_state;
        const c_size = d_model * d_state;
        const d_size = d_model;
        const delta_size = seq_len * d_model;
        const hidden_size = d_model * d_state;
        const output_size = seq_len * d_model;

        var self = Self{
            .allocator = allocator,
            .d_model = d_model,
            .d_state = d_state,
            .seq_len = seq_len,
            .A_matrix = try allocator.alloc(f32, a_size),
            .B_matrix = try allocator.alloc(f32, b_size),
            .C_matrix = try allocator.alloc(f32, c_size),
            .D_matrix = try allocator.alloc(f32, d_size),
            .delta_proj = try allocator.alloc(f32, delta_size),
            .hidden_state = try allocator.alloc(f32, hidden_size),
            .output_buffer = try allocator.alloc(f32, output_size),
        };

        self.initializeMatrices();
        return self;
    }

    pub fn deinit(self: *Self) void {
        self.allocator.free(self.A_matrix);
        self.allocator.free(self.B_matrix);
        self.allocator.free(self.C_matrix);
        self.allocator.free(self.D_matrix);
        self.allocator.free(self.delta_proj);
        self.allocator.free(self.hidden_state);
        self.allocator.free(self.output_buffer);
    }

    fn initializeMatrices(self: *Self) void {
        var rng = std.rand.DefaultPrng.init(@intCast(std.time.timestamp()));
        const random = rng.random();

        for (self.A_matrix) |*val| {
            val.* = random.floatNorm(f32) * 0.1;
        }
        for (self.B_matrix) |*val| {
            val.* = random.floatNorm(f32) * 0.1;
        }
        for (self.C_matrix) |*val| {
            val.* = random.floatNorm(f32) * 0.1;
        }
        for (self.D_matrix) |*val| {
            val.* = random.floatNorm(f32) * 0.1;
        }

        std.mem.set(f32, self.hidden_state, 0.0);
    }

    pub fn forward(self: *Self, input_tokens: []const u32) ![]u32 {
        const batch_size = input_tokens.len;
        var output_tokens = try self.allocator.alloc(u32, batch_size);

        for (input_tokens, 0..) |token, t| {
            const x_t = @as(f32, @floatFromInt(token));

            for (0..self.d_model) |i| {
                var h_new: f32 = 0.0;
                for (0..self.d_state) |j| {
                    const idx = i * self.d_state + j;
                    const delta = self.delta_proj[t * self.d_model + i];
                    const A_bar = 1.0 + delta * self.A_matrix[idx];
                    const B_bar = delta * self.B_matrix[idx];
                    h_new += A_bar * self.hidden_state[idx] + B_bar * x_t;
                }

                var y: f32 = 0.0;
                for (0..self.d_state) |j| {
                    const idx = i * self.d_state + j;
                    y += self.C_matrix[idx] * self.hidden_state[idx];
                }
                y += self.D_matrix[i] * x_t;

                self.output_buffer[t * self.d_model + i] = y;

                for (0..self.d_state) |j| {
                    const idx = i * self.d_state + j;
                    self.hidden_state[idx] = h_new;
                }
            }

            output_tokens[t] = @intFromFloat(@max(0, @min(65535, self.output_buffer[t * self.d_model])));
        }

        return output_tokens;
    }
};

// tokenizer/synapse.zig
const std = @import("std");

pub const SynapseTokenizer = struct {
    allocator: std.mem.Allocator,
    vocab: std.HashMap([]const u8, u32, std.hash_map.StringContext, std.hash_map.default_max_load_percentage),
    reverse_vocab: std.HashMap(u32, []const u8, std.hash_map.AutoContext(u32), std.hash_map.default_max_load_percentage),
    merge_rules: std.ArrayList(MergeRule),
    next_token_id: u32,

    const MergeRule = struct {
        p1: u32,
        p2: u32,
        new_token: u32,
    };

    const Self = @This();

    pub fn init(allocator: std.mem.Allocator) !Self {
        var self = Self{
            .allocator = allocator,
            .vocab = std.HashMap([]const u8, u32, std.hash_map.StringContext, std.hash_map.default_max_load_percentage).init(allocator),
            .reverse_vocab = std.HashMap(u32, []const u8, std.hash_map.AutoContext(u32), std.hash_map.default_max_load_percentage).init(allocator),
            .merge_rules = std.ArrayList(MergeRule).init(allocator),
            .next_token_id = 256,
        };

        try self.initializeBaseVocab();
        return self;
    }

    pub fn deinit(self: *Self) void {
        self.vocab.deinit();
        self.reverse_vocab.deinit();
        self.merge_rules.deinit();
    }

    fn initializeBaseVocab(self: *Self) !void {
        for (0..256) |i| {
            const byte_str = try self.allocator.alloc(u8, 1);
            byte_str[0] = @intCast(i);
            try self.vocab.put(byte_str, @intCast(i));
            try self.reverse_vocab.put(@intCast(i), byte_str);
        }
    }

    pub fn encode(self: *Self, text: []const u8) ![]u32 {
        var tokens = std.ArrayList(u32).init(self.allocator);
        defer tokens.deinit();

        for (text) |byte| {
            try tokens.append(byte);
        }

        var changed = true;
        while (changed) {
            changed = false;
            const most_frequent_pair = self.findMostFrequentPair(tokens.items);
            if (most_frequent_pair.freq >= 2) {
                try self.applyMergeRule(tokens.items, most_frequent_pair);
                changed = true;
            }
        }

        return try tokens.toOwnedSlice();
    }

    pub fn decode(self: *Self, tokens: []const u32) ![]u8 {
        var result = std.ArrayList(u8).init(self.allocator);
        defer result.deinit();

        for (tokens) |token| {
            if (self.reverse_vocab.get(token)) |token_str| {
                try result.appendSlice(token_str);
            } else {
                try result.append(@intCast(token % 256));
            }
        }

        return try result.toOwnedSlice();
    }

    const PairFreq = struct {
        p1: u32,
        p2: u32,
        freq: u32,
    };

    fn findMostFrequentPair(self: *Self, tokens: []const u32) PairFreq {
        var pair_counts = std.HashMap([2]u32, u32, std.hash_map.AutoContext([2]u32), std.hash_map.default_max_load_percentage).init(self.allocator);
        defer pair_counts.deinit();

        for (tokens[0..tokens.len-1], 0..) |token, i| {
            const pair = [2]u32{token, tokens[i+1]};
            const count = pair_counts.get(pair) orelse 0;
            pair_counts.put(pair, count + 1) catch continue;
        }

        var best_pair = PairFreq{ .p1 = 0, .p2 = 0, .freq = 0 };
        var iterator = pair_counts.iterator();
        while (iterator.next()) |entry| {
            if (entry.value_ptr.* > best_pair.freq) {
                best_pair = PairFreq{ .p1 = entry.key_ptr.*[0], .p2 = entry.key_ptr.*[1], .freq = entry.value_ptr.* };
            }
        }

        return best_pair;
    }

    fn applyMergeRule(self: *Self, tokens: []u32, rule: PairFreq) !void {
        const merge_rule = MergeRule{ .p1 = rule.p1, .p2 = rule.p2, .new_token = self.next_token_id };
        try self.merge_rules.append(merge_rule);
        self.next_token_id += 1;

        var i: usize = 0;
        while (i < tokens.len - 1) {
            if (tokens[i] == rule.p1 and tokens[i + 1] == rule.p2) {
                tokens[i] = merge_rule.new_token;
                for (i + 1..tokens.len - 1) |j| {
                    tokens[j] = tokens[j + 1];
                }
                i += 1;
            } else {
                i += 1;
            }
        }
    }
};

// pipeline/aethelred.zig
const std = @import("std");

pub const Pipeline = struct {
    allocator: std.mem.Allocator,
    batch_size: u32,
    sequence_length: u32,
    processing_queue: std.ArrayList(ProcessingTask),

    const ProcessingTask = struct {
        data: []u8,
        priority: u8,
        timestamp: i64,
    };

    const Self = @This();

    pub fn init(allocator: std.mem.Allocator) !Self {
        return Self{
            .allocator = allocator,
            .batch_size = 32,
            .sequence_length = 2048,
            .processing_queue = std.ArrayList(ProcessingTask).init(allocator),
        };
    }

    pub fn deinit(self: *Self) void {
        for (self.processing_queue.items) |task| {
            self.allocator.free(task.data);
        }
        self.processing_queue.deinit();
    }

    pub fn processDataset(self: *Self, dataset_path: []const u8) !bool {
        const file = std.fs.cwd().openFile(dataset_path, .{}) catch return false;
        defer file.close();

        const file_size = try file.getEndPos();
        const content = try self.allocator.alloc(u8, file_size);
        defer self.allocator.free(content);

        _ = try file.readAll(content);

        var chunks = std.ArrayList([]u8).init(self.allocator);
        defer {
            for (chunks.items) |chunk| {
                self.allocator.free(chunk);
            }
            chunks.deinit();
        }

        const chunk_size = 1024;
        var i: usize = 0;
        while (i < content.len) {
            const end = @min(i + chunk_size, content.len);
            const chunk = try self.allocator.dupe(u8, content[i..end]);
            try chunks.append(chunk);
            i += chunk_size;
        }

        for (chunks.items) |chunk| {
            const task = ProcessingTask{
                .data = chunk,
                .priority = 1,
                .timestamp = std.time.timestamp(),
            };
            try self.processing_queue.append(task);
        }

        return self.processBatch();
    }

    fn processBatch(self: *Self) bool {
        for (self.processing_queue.items) |task| {
            std.log.info("Processing chunk of size {}", .{task.data.len});
            std.time.sleep(std.time.ns_per_ms * 100);
        }
        return true;
    }
};

// nim_scheduler.nim
import threadpool, locks, times, deques, tables, random
import algorithm, sequtils, strformat

type
  TaskPriority = enum
    tpLow = 0, tpNormal = 1, tpHigh = 2, tpCritical = 3

  Task = object
    id: int
    priority: TaskPriority
    data: seq[byte]
    createdAt: Time
    processingTime: float

  WorkerState = enum
    wsIdle, wsWorking, wsStealing

  Worker = object
    id: int
    state: WorkerState
    localQueue: Deque[Task]
    processedTasks: int
    totalProcessingTime: float

  NimScheduler = object
    workers: seq[Worker]
    globalQueue: Deque[Task]
    completedTasks: Table[int, Task]
    lock: Lock
    shutdown: bool
    taskIdCounter: int

var scheduler: NimScheduler

proc initScheduler*(numWorkers: int = 8) =
  scheduler.workers = newSeqOfCap[Worker](numWorkers)
  scheduler.globalQueue = initDeque
  scheduler.completedTasks = initTable
  scheduler.lock.initLock()
  scheduler.shutdown = false
  scheduler.taskIdCounter = 0

  for i in 0..<numWorkers:
    let worker = Worker(
      id: i,
      state: wsIdle,
      localQueue: initDeque,
      processedTasks: 0,
      totalProcessingTime: 0.0
    )
    scheduler.workers.add(worker)

proc submitTask*(data: seq[byte], priority: TaskPriority = tpNormal): int =
  scheduler.lock.acquire()
  defer: scheduler.lock.release()

  let task = Task(
    id: scheduler.taskIdCounter,
    priority: priority,
    data: data,
    createdAt: now(),
    processingTime: 0.0
  )

  scheduler.taskIdCounter.inc()
  scheduler.globalQueue.addLast(task)
  return task.id

proc stealWork(workerId: int): bool =
  let victimId = rand(scheduler.workers.len)
  if victimId == workerId:
    return false

  scheduler.lock.acquire()
  defer: scheduler.lock.release()

  if scheduler.workers[victimId].localQueue.len > 1:
    let stolenTask = scheduler.workers[victimId].localQueue.popFirst()
    scheduler.workers[workerId].localQueue.addLast(stolenTask)
    return true

  return false

proc processTask(task: Task): Task =
  let startTime = cpuTime()

  # Simulate actual work based on task data
  var checksum: uint32 = 0
  for b in task.data:
    checksum = checksum xor uint32(b)

  # Variable processing time based on data complexity
  let sleepTime = max(10, int(checksum mod 100))
  sleep(sleepTime)

  result = task
  result.processingTime = cpuTime() - startTime

proc workerMain(workerId: int) {.thread.} =
  while not scheduler.shutdown:
    var currentTask: Task
    var hasTask = false

    # Try to get task from local queue first
    scheduler.lock.acquire()
    if scheduler.workers[workerId].localQueue.len > 0:
      currentTask = scheduler.workers[workerId].localQueue.popFirst()
      hasTask = true
      scheduler.workers[workerId].state = wsWorking
    scheduler.lock.release()

    # If no local task, try global queue
    if not hasTask:
      scheduler.lock.acquire()
      if scheduler.globalQueue.len > 0:
        currentTask = scheduler.globalQueue.popFirst()
        hasTask = true
        scheduler.workers[workerId].state = wsWorking
      scheduler.lock.release()

    # If still no task, try work stealing
    if not hasTask:
      scheduler.workers[workerId].state = wsStealing
      if stealWork(workerId):
        scheduler.lock.acquire()
        if scheduler.workers[workerId].localQueue.len > 0:
          currentTask = scheduler.workers[workerId].localQueue.popFirst()
          hasTask = true
          scheduler.workers[workerId].state = wsWorking
        scheduler.lock.release()

    if hasTask:
      let processedTask = processTask(currentTask)

      scheduler.lock.acquire()
      scheduler.completedTasks[processedTask.id] = processedTask
      scheduler.workers[workerId].processedTasks.inc()
      scheduler.workers[workerId].totalProcessingTime += processedTask.processingTime
      scheduler.workers[workerId].state = wsIdle
      scheduler.lock.release()
    else:
      scheduler.workers[workerId].state = wsIdle
      sleep(1)

var workerThreads: seq[Thread[int]]

proc startScheduler*() =
  workerThreads = newSeq[Thread[int]](scheduler.workers.len)

  for i in 0..<scheduler.workers.len:
    createThread(workerThreads[i], workerMain, i)

proc stopScheduler*() =
  scheduler.shutdown = true

  for thread in workerThreads:
    joinThread(thread)

proc getSchedulerStats*(): string =
  scheduler.lock.acquire()
  defer: scheduler.lock.release()

  let totalProcessed = scheduler.workers.mapIt(it.processedTasks).foldl(a + b, 0)
  let totalTime = scheduler.workers.mapIt(it.totalProcessingTime).foldl(a + b, 0.0)
  let avgTime = if totalProcessed > 0: totalTime / float(totalProcessed) else: 0.0

  result = fmt"""
Scheduler Statistics:
- Total tasks processed: {totalProcessed}
- Total processing time: {totalTime:.2f}s
- Average task time: {avgTime:.4f}s
- Pending tasks: {scheduler.globalQueue.len}
- Completed tasks: {scheduler.completedTasks.len}
"""

# main.futhark
-- JAIDE V25 - Futhark GPU Acceleration Layer
let dotProduct [n] (xs: [n]f32) (ys: [n]f32): f32 =
  reduce (+) 0 (map2 (*) xs ys)

let matrixVectorMul [n][m] (matrix: [n][m]f32) (vector: [m]f32): [n]f32 =
  map (dotProduct vector) matrix

let vectorAdd [n] (xs: [n]f32) (ys: [n]f32): [n]f32 =
  map2 (+) xs ys

let vectorScale [n] (alpha: f32) (xs: [n]f32): [n]f32 =
  map (* alpha) xs

let activation [n] (xs: [n]f32): [n]f32 =
  map (\x -> 1.0 / (1.0 + f32.exp(-x))) xs

let jadeSSMStep [d_model][d_state] 
    (A_matrix: [d_model][d_state]f32) 
    (B_matrix: [d_model][d_state]f32)
    (C_matrix: [d_model][d_state]f32)
    (D_matrix: [d_model]f32)
    (delta: [d_model]f32)
    (x_t: [d_model]f32)
    (h_prev: [d_model][d_state]f32): ([d_model][d_state]f32, [d_model]f32) =

  let A_bar = map2 (\row del -> map (* (1.0 + del)) row) A_matrix delta
  let B_bar = map2 (\row del -> map (* del) row) B_matrix delta

  let h_new = map3 (\a_row b_row h_row -> 
    vectorAdd (map2 (*) a_row h_row) (map (* (reduce (+) 0 x_t)) b_row)
  ) A_bar B_bar h_prev

  let y_t = map2 (\c_row h_row -> 
    dotProduct c_row h_row
  ) C_matrix h_new

  let output = vectorAdd y_t (map2 (*) D_matrix x_t)

  in (h_new, activation output)

let jadeSSMForward [seq_len][d_model][d_state]
    (A_matrix: [d_model][d_state]f32)
    (B_matrix: [d_model][d_state]f32) 
    (C_matrix: [d_model][d_state]f32)
    (D_matrix: [d_model]f32)
    (deltas: [seq_len][d_model]f32)
    (inputs: [seq_len][d_model]f32)
    (h_init: [d_model][d_state]f32): ([seq_len][d_model]f32, [d_model][d_state]f32) =

  let (_, outputs, final_state) = loop (h, outputs, i) = (h_init, replicate seq_len (replicate d_model 0.0), 0) 
    while i < seq_len do
    let (h_new, y_t) = jadeSSMStep A_matrix B_matrix C_matrix D_matrix deltas[i] inputs[i] h
    in (h_new, outputs with [i] = y_t, i + 1)

  in (outputs, final_state)

let batchedJadeSSM [batch_size][seq_len][d_model][d_state]
    (A_matrices: [batch_size][d_model][d_state]f32)
    (B_matrices: [batch_size][d_model][d_state]f32)
    (C_matrices: [batch_size][d_model][d_state]f32) 
    (D_matrices: [batch_size][d_model]f32)
    (deltas: [batch_size][seq_len][d_model]f32)
    (inputs: [batch_size][seq_len][d_model]f32)
    (h_inits: [batch_size][d_model][d_state]f32): [batch_size][seq_len][d_model]f32 =

  let results = map6 jadeSSMForward A_matrices B_matrices C_matrices D_matrices deltas inputs h_inits
  in map (.0) results

let layerNorm [n] (epsilon: f32) (xs: [n]f32): [n]f32 =
  let mean = (reduce (+) 0 xs) / f32.i64 n
  let variance = (reduce (+) 0 (map (\x -> (x - mean) * (x - mean)) xs)) / f32.i64 n
  let std = f32.sqrt (variance + epsilon)
  in map (\x -> (x - mean) / std) xs

let multiHeadAttention [seq_len][d_model][n_heads]
    (queries: [seq_len][d_model]f32)
    (keys: [seq_len][d_model]f32) 
    (values: [seq_len][d_model]f32): [seq_len][d_model]f32 =

  let d_k = d_model / n_heads
  let scale = 1.0 / f32.sqrt (f32.i64 d_k)

  let reshaped_q = unflatten queries
  let reshaped_k = unflatten keys
  let reshaped_v = unflatten values

  let attention_scores = map (\q_head -> 
    map (\k_head -> 
      scale * dotProduct q_head k_head
    ) reshaped_k
  ) reshaped_q

  let attention_weights = map (map (\scores -> 
    let max_score = reduce f32.max f32.lowest scores
    let exp_scores = map (\s -> f32.exp (s - max_score)) scores
    let sum_exp = reduce (+) 0 exp_scores
    in map (/ sum_exp) exp_scores
  )) attention_scores

  let attended_values = map2 (\weights v_heads ->
    map (\v_head ->
      reduce (+) 0 (map2 (*) weights v_head)
    ) v_heads
  ) attention_weights reshaped_v

  in flatten attended_values

entry jadeInference [batch_size][seq_len][d_model][d_state][n_heads]
    (A_matrices: [batch_size][d_model][d_state]f32)
    (B_matrices: [batch_size][d_model][d_state]f32)
    (C_matrices: [batch_size][d_model][d_state]f32)
    (D_matrices: [batch_size][d_model]f32)
    (deltas: [batch_size][seq_len][d_model]f32)
    (inputs: [batch_size][seq_len][d_model]f32)
    (h_inits: [batch_size][d_model][d_state]f32): [batch_size][seq_len][d_model]f32 =

  batchedJadeSSM A_matrices B_matrices C_matrices D_matrices deltas inputs h_inits

-- chapel_distributed.chpl
use BlockDist, Time, Random, IO;

config const numNodes = 4;
config const d_model = 8192; 
config const d_state = 256;
config const seq_len = 2048;
config const batch_size = 32;

class JadeDistributedTraining {
  const targetLocales = Locales[0..#numNodes];
  const distributedDomain = {0..#batch_size} dmapped Block(boundingBox={0..#batch_size}, targetLocales=targetLocales);

  var A_matrices: [distributedDomain][d_model][d_state] real(32);
  var B_matrices: [distributedDomain][d_model][d_state] real(32);
  var C_matrices: [distributedDomain][d_model][d_state] real(32);
  var D_matrices: [distributedDomain][d_model] real(32);

  var gradients_A: [distributedDomain][d_model][d_state] real(32);
  var gradients_B: [distributedDomain][d_model][d_state] real(32);
  var gradients_C: [distributedDomain][d_model][d_state] real(32);
  var gradients_D: [distributedDomain][d_model] real(32);

  var learning_rate: real(32) = 0.001;
  var momentum: real(32) = 0.9;
  var velocity_A: [distributedDomain][d_model][d_state] real(32);
  var velocity_B: [distributedDomain][d_model][d_state] real(32);
  var velocity_C: [distributedDomain][d_state] real(32);
  var velocity_D: [distributedDomain][d_model] real(32);

  proc init() {
    this.complete();
    initializeMatrices();
  }

  proc initializeMatrices() {
    var rng = new RandomStream(real(32), seed=42);

    forall (i, j, k) in {distributedDomain, 0..#d_model, 0..#d_state} {
      A_matrices[i][j][k] = rng.getNext() * 0.1;
      B_matrices[i][j][k] = rng.getNext() * 0.1;  
      C_matrices[i][j][k] = rng.getNext() * 0.1;
      velocity_A[i][j][k] = 0.0;
      velocity_B[i][j][k] = 0.0;
      velocity_C[i][j][k] = 0.0;
    }

    forall (i, j) in {distributedDomain, 0..#d_model} {
      D_matrices[i][j] = rng.getNext() * 0.1;
      velocity_D[i][j] = 0.0;
    }
  }

  proc forwardPass(inputs: [distributedDomain][seq_len][d_model] real(32)): 
    [distributedDomain][seq_len][d_model] real(32) {

    var outputs: [distributedDomain][seq_len][d_model] real(32);
    var hidden_states: [distributedDomain][d_model][d_state] real(32);

    coforall loc in targetLocales do on loc {
      forall batch_idx in distributedDomain.localSubdomain() {
        var h_t = hidden_states[batch_idx];

        for t in 0..#seq_len {
          for i in 0..#d_model {
            var h_new: real(32) = 0.0;

            for j in 0..#d_state {
              const delta = 0.1; // Simplified delta
              const A_bar = 1.0 + delta * A_matrices[batch_idx][i][j];
              const B_bar = delta * B_matrices[batch_idx][i][j];
              h_new += A_bar * h_t[i][j] + B_bar * inputs[batch_idx][t][i];
            }

            var y: real(32) = 0.0;
            for j in 0..#d_state {
              y += C_matrices[batch_idx][i][j] * h_t[i][j];
            }
            y += D_matrices[batch_idx][i] * inputs[batch_idx][t][i];

            outputs[batch_idx][t][i] = tanh(y);

            for j in 0..#d_state {
              h_t[i][j] = h_new;
            }
          }
        }
        hidden_states[batch_idx] = h_t;
      }
    }

    return outputs;
  }

  proc computeGradients(inputs: [distributedDomain][seq_len][d_model] real(32),
                       targets: [distributedDomain][seq_len][d_model] real(32),
                       outputs: [distributedDomain][seq_len][d_model] real(32)) {

    coforall loc in targetLocales do on loc {
      forall batch_idx in distributedDomain.localSubdomain() {
        for i in 0..#d_model {
          for j in 0..#d_state {
            var grad_A: real(32) = 0.0;
            var grad_B: real(32) = 0.0;
            var grad_C: real(32) = 0.0;

            for t in 0..#seq_len {
              const error = outputs[batch_idx][t][i] - targets[batch_idx][t][i];
              grad_A += error * inputs[batch_idx][t][i];
              grad_B += error * inputs[batch_idx][t][i];
              grad_C += error * inputs[batch_idx][t][i];
            }

            gradients_A[batch_idx][i][j] = grad_A / seq_len;
            gradients_B[batch_idx][i][j] = grad_B / seq_len;
            gradients_C[batch_idx][i][j] = grad_C / seq_len;
          }

          var grad_D: real(32) = 0.0;
          for t in 0..#seq_len {
            const error = outputs[batch_idx][t][i] - targets[batch_idx][t][i];
            grad_D += error;
          }
          gradients_D[batch_idx][i] = grad_D / seq_len;
        }
      }
    }
  }

  proc allReduceGradients() {
    var global_grad_A: [d_model][d_state] real(32);
    var global_grad_B: [d_model][d_state] real(32);
    var global_grad_C: [d_model][d_state] real(32);
    var global_grad_D: [d_model] real(32);

    for i in 0..#d_model {
      for j in 0..#d_state {
        global_grad_A[i][j] = + reduce gradients_A[..][i][j];
        global_grad_B[i][j] = + reduce gradients_B[..][i][j];
        global_grad_C[i][j] = + reduce gradients_C[..][i][j];
      }
      global_grad_D[i] = + reduce gradients_D[..][i];
    }

    const n_workers = batch_size;
    global_grad_A /= n_workers;
    global_grad_B /= n_workers;
    global_grad_C /= n_workers;
    global_grad_D /= n_workers;

    forall batch_idx in distributedDomain {
      gradients_A[batch_idx] = global_grad_A;
      gradients_B[batch_idx] = global_grad_B;
      gradients_C[batch_idx] = global_grad_C;
      gradients_D[batch_idx] = global_grad_D;
    }
  }

  proc updateWeights() {
    coforall loc in targetLocales do on loc {
      forall batch_idx in distributedDomain.localSubdomain() {
        for i in 0..#d_model {
          for j in 0..#d_state {
            velocity_A[batch_idx][i][j] = momentum * velocity_A[batch_idx][i][j] - learning_rate * gradients_A[batch_idx][i][j];
            velocity_B[batch_idx][i][j] = momentum * velocity_B[batch_idx][i][j] - learning_rate * gradients_B[batch_idx][i][j];
            velocity_C[batch_idx][i][j] = momentum * velocity_C[batch_idx][i][j] - learning_rate * gradients_C[batch_idx][i][j];

            A_matrices[batch_idx][i][j] += velocity_A[batch_idx][i][j];
            B_matrices[batch_idx][i][j] += velocity_B[batch_idx][i][j];
            C_matrices[batch_idx][i][j] += velocity_C[batch_idx][i][j];
          }

          velocity_D[batch_idx][i] = momentum * velocity_D[batch_idx][i] - learning_rate * gradients_D[batch_idx][i];
          D_matrices[batch_idx][i] += velocity_D[batch_idx][i];
        }
      }
    }
  }

  proc trainEpoch(inputs: [distributedDomain][seq_len][d_model] real(32),
                 targets: [distributedDomain][seq_len][d_model] real(32)): real(32) {

    const timer = new Timer();
    timer.start();

    const outputs = forwardPass(inputs);
    computeGradients(inputs, targets, outputs);
    allReduceGradients();
    updateWeights();

    timer.stop();

    var total_loss: real(32) = 0.0;
    forall batch_idx in distributedDomain with (+ reduce total_loss) {
      for t in 0..#seq_len {
        for i in 0..#d_model {
          const error = outputs[batch_idx][t][i] - targets[batch_idx][t][i];
          total_loss += error * error;
        }
      }
    }

    total_loss /= (batch_size * seq_len * d_model);

    writeln("Epoch completed in ", timer.elapsed(), " seconds, Loss: ", total_loss);
    return total_loss;
  }
}

proc main() {
  var trainer = new JadeDistributedTraining();
  var rng = new RandomStream(real(32), seed=123);

  var inputs: [trainer.distributedDomain][seq_len][d_model] real(32);
  var targets: [trainer.distributedDomain][seq_len][d_model] real(32);

  forall (i, t, d) in {trainer.distributedDomain, 0..#seq_len, 0..#d_model} {
    inputs[i][t][d] = rng.getNext();
    targets[i][t][d] = rng.getNext();
  }

  const num_epochs = 100;
  for epoch in 1..num_epochs {
    writeln("Starting epoch ", epoch);
    const loss = trainer.trainEpoch(inputs, targets);

    if epoch % 10 == 0 {
      writeln("Epoch ", epoch, " completed with loss: ", loss);
    }
  }

  writeln("Training completed.");
}

// balsa_hardware_design.balsa
import [balsa.sim]
import [balsa.channel]
import [balsa.compat.builtin]

type Word is 32 bits
type StateVector is array [0..255] of Word
type ModelVector is array [0..8191] of Word

procedure JadeSSMCore (
    input clk: bit;
    input reset: bit;
    input start: bit;
    input A_matrix: array [0..8191] of array [0..255] of Word;
    input B_matrix: array [0..8191] of array [0..255] of Word;
    input C_matrix: array [0..8191] of array [0..255] of Word;
    input D_vector: array [0..8191] of Word;
    input delta_vector: array [0..8191] of Word;
    input x_input: array [0..8191] of Word;
    input h_previous: array [0..8191] of array [0..255] of Word;
    output y_output: array [0..8191] of Word;
    output h_output: array [0..8191] of array [0..255] of Word;
    output done: bit
) is
local
    variable i, j: cardinal;
    variable temp_a, temp_b, temp_h, temp_y: Word;
    variable state: (idle, compute_h, compute_y, finish);
    channel sync_start, sync_done: sync;
begin
    state := idle;
    i := 0;
    j := 0;
    done := 0;

    loop
        select
            start & (state = idle) then
                sync_start!;
                state := compute_h;
                i := 0;
                j := 0
        or
            (state = compute_h) then
                -- Compute h_new[i][j] = A_bar[i][j] * h_prev[i][j] + B_bar[i][j] * x[i]
                temp_a := A_matrix[i][j] * (1 + delta_vector[i] * A_matrix[i][j]);
                temp_b := B_matrix[i][j] * delta_vector[i];
                temp_h := temp_a * h_previous[i][j] + temp_b * x_input[i];
                h_output[i][j] := temp_h;

                j := j + 1;
                if j >= 256 then
                    j := 0;
                    i := i + 1;
                    if i >= 8192 then
                        state := compute_y;
                        i := 0
                    end
                end
        or
            (state = compute_y) then
                -- Compute y[i] = sum(C[i][j] * h[i][j]) + D[i] * x[i]
                temp_y := D_vector[i] * x_input[i];
                for j := 0 to 255 do
                    temp_y := temp_y + (C_matrix[i][j] * h_output[i][j])
                end;
                y_output[i] := temp_y;

                i := i + 1;
                if i >= 8192 then
                    state := finish
                end
        or
            (state = finish) then
                done := 1;
                sync_done!;
                state := idle
        end
    end
end

procedure JadeAccelerator (
    input clk: bit;
    input reset: bit;
    input memory_read_req: sync;
    input memory_write_req: sync;
    input memory_addr: Word;
    input memory_data_in: Word;
    output memory_data_out: Word;
    output memory_ready: bit;
    input compute_req: sync;
    output compute_done: sync
) is
local
    array [0..1023] of Word memory_bank;
    variable addr_index: cardinal;
    variable compute_state: (idle, loading, computing, storing);
    variable core_start, core_done: bit;
    array [0..8191] of array [0..255] of Word A_matrix, B_matrix, C_matrix, h_state;
    array [0..8191] of Word D_vector, delta_vector, x_vector, y_result;
    channel memory_sync, compute_sync: sync;
begin
    compute_state := idle;
    memory_ready := 1;
    core_start := 0;

    -- Memory Controller
    loop
        select
            memory_read_req then
                addr_index := memory_addr mod 1024;
                memory_data_out := memory_bank[addr_index];
                memory_ready := 1
        or
            memory_write_req then
                addr_index := memory_addr mod 1024;
                memory_bank[addr_index] := memory_data_in;
                memory_ready := 1
        end
    end ||

    -- Compute Controller
    loop
        select
            compute_req & (compute_state = idle) then
                compute_state := loading;
                -- Load matrices from memory (simplified)
                for i := 0 to 8191 do
                    for j := 0 to 255 do
                        A_matrix[i][j] := memory_bank[(i * 256 + j) mod 1024];
                        B_matrix[i][j] := memory_bank[(i * 256 + j + 8192 * 256) mod 1024];
                        C_matrix[i][j] := memory_bank[(i * 256 + j + 2 * 8192 * 256) mod 1024];
                        h_state[i][j] := 0
                    end;
                    D_vector[i] := memory_bank[(i + 3 * 8192 * 256) mod 1024];
                    delta_vector[i] := memory_bank[(i + 3 * 8192 * 256 + 8192) mod 1024];
                    x_vector[i] := memory_bank[(i + 3 * 8192 * 256 + 2 * 8192) mod 1024]
                end;
                compute_state := computing;
                core_start := 1
        or
            core_done & (compute_state = computing) then
                compute_state := storing;
                core_start := 0;
                -- Store results back to memory
                for i := 0 to 8191 do
                    memory_bank[(i + 3 * 8192 * 256 + 3 * 8192) mod 1024] := y_result[i];
                    for j := 0 to 255 do
                        memory_bank[(i * 256 + j + 4 * 8192 * 256) mod 1024] := h_state[i][j]
                    end
                end;
                compute_state := idle;
                compute_done!
        end
    end ||

    -- SSM Core Instance
    JadeSSMCore(clk, reset, core_start, A_matrix, B_matrix, C_matrix, 
                D_vector, delta_vector, x_vector, h_state, y_result, h_state, core_done)
end

// llvm_kernels.ll
; JAIDE V25 - LLVM IR for Core SSM Kernel
; Optimized LLVM IR for the State Space Model forward pass

target datalayout = "e-m:e-p270:32:32-p271:32:32-p272:64:64-i64:64-f80:128-n8:16:32:64-S128"
target triple = "x86_64-unknown-linux-gnu"

declare void @llvm.memcpy.p0i8.p0i8.i64(i8* noalias nocapture writeonly, i8* noalias nocapture readonly, i64, i1 immarg) #1
declare float @llvm.fmuladd.f32(float, float, float) #2
declare <8 x float> @llvm.fmuladd.v8f32(<8 x float>, <8 x float>, <8 x float>) #2
declare float @llvm.exp.f32(float) #2
declare <8 x float> @llvm.exp.v8f32(<8 x float>) #2
declare float @llvm.tanh.f32(float) #2
declare <8 x float> @llvm.tanh.v8f32(<8 x float>) #2

define void @jade_ssm_forward_single(
    float* noalias nocapture readonly %A_matrix,
    float* noalias nocapture readonly %B_matrix, 
    float* noalias nocapture readonly %C_matrix,
    float* noalias nocapture readonly %D_vector,
    float* noalias nocapture readonly %delta_vector,
    float* noalias nocapture readonly %x_input,
    float* noalias nocapture %h_state,
    float* noalias nocapture writeonly %y_output,
    i32 %d_model,
    i32 %d_state
) #0 {
entry:
  %d_model_i64 = zext i32 %d_model to i64
  %d_state_i64 = zext i32 %d_state to i64
  %total_state_elements = mul nuw i64 %d_model_i64, %d_state_i64

  br label %model_loop

model_loop:
  %i = phi i64 [ 0, %entry ], [ %i_next, %model_loop_end ]
  %i_cmp = icmp ult i64 %i, %d_model_i64
  br i1 %i_cmp, label %model_body, label %exit

model_body:
  %delta_i_ptr = getelementptr inbounds float, float* %delta_vector, i64 %i
  %delta_i = load float, float* %delta_i_ptr, align 4, !tbaa !4
  %x_i_ptr = getelementptr inbounds float, float* %x_input, i64 %i
  %x_i = load float, float* %x_i_ptr, align 4, !tbaa !4
  %d_i_ptr = getelementptr inbounds float, float* %D_vector, i64 %i
  %d_i = load float, float* %d_i_ptr, align 4, !tbaa !4

  %one = fpext float 1.0 to float

  ; Initialize accumulator for h_new computation
  %h_new_accumulator = alloca float, align 4
  store float 0.0, float* %h_new_accumulator, align 4

  ; Initialize accumulator for y computation  
  %y_accumulator = alloca float, align 4
  %dy_contribution = fmul fast float %d_i, %x_i
  store float %dy_contribution, float* %y_accumulator, align 4

  br label %state_loop

state_loop:
  %j = phi i64 [ 0, %model_body ], [ %j_next, %state_loop_body ]
  %j_cmp = icmp ult i64 %j, %d_state_i64
  br i1 %j_cmp, label %state_loop_body, label %state_loop_end

state_loop_body:
  ; Calculate matrix indices
  %matrix_idx = add nuw i64 %j, %state_offset
  %state_offset = mul nuw i64 %i, %d_state_i64

  ; Load matrix elements
  %a_ij_ptr = getelementptr inbounds float, float* %A_matrix, i64 %matrix_idx
  %a_ij = load float, float* %a_ij_ptr, align 4, !tbaa !4
  %b_ij_ptr = getelementptr inbounds float, float* %B_matrix, i64 %matrix_idx
  %b_ij = load float, float* %b_ij_ptr, align 4, !tbaa !4
  %c_ij_ptr = getelementptr inbounds float, float* %C_matrix, i64 %matrix_idx
  %c_ij = load float, float* %c_ij_ptr, align 4, !tbaa !4

  ; Load previous hidden state
  %h_prev_ij_ptr = getelementptr inbounds float, float* %h_state, i64 %matrix_idx
  %h_prev_ij = load float, float* %h_prev_ij_ptr, align 4, !tbaa !4

  ; Compute discretized matrices A_bar and B_bar
  %delta_a_ij = fmul fast float %delta_i, %a_ij
  %a_bar_ij = fadd fast float %one, %delta_a_ij
  %b_bar_ij = fmul fast float %delta_i, %b_ij

  ; Compute h_new contribution: A_bar * h_prev + B_bar * x
  %ah_contrib = fmul fast float %a_bar_ij, %h_prev_ij
  %bx_contrib = fmul fast float %b_bar_ij, %x_i
  %h_new_contrib = fadd fast float %ah_contrib, %bx_contrib

  ; Accumulate h_new
  %h_acc_old = load float, float* %h_new_accumulator, align 4
  %h_acc_new = fadd fast float %h_acc_old, %h_new_contrib
  store float %h_acc_new, float* %h_new_accumulator, align 4

  ; Compute y contribution: C * h_prev  
  %cy_contrib = fmul fast float %c_ij, %h_prev_ij
  %y_acc_old = load float, float* %y_accumulator, align 4
  %y_acc_new = fadd fast float %y_acc_old, %cy_contrib
  store float %y_acc_new, float* %y_accumulator, align 4

  ; Update hidden state in place
  store float %h_new_contrib, float* %h_prev_ij_ptr, align 4, !tbaa !4

  %j_next = add nuw i64 %j, 1
  br label %state_loop

state_loop_end:
  ; Store final output
  %y_final = load float, float* %y_accumulator, align 4
  %y_activated = call fast float @llvm.tanh.f32(float %y_final)
  %y_output_i_ptr = getelementptr inbounds float, float* %y_output, i64 %i  
  store float %y_activated, float* %y_output_i_ptr, align 4, !tbaa !4

  br label %model_loop_end

model_loop_end:
  %i_next = add nuw i64 %i, 1
  br label %model_loop

exit:
  ret void
}

define void @jade_ssm_forward_vectorized(
    float* noalias nocapture readonly %A_matrix,
    float* noalias nocapture readonly %B_matrix,
    float* noalias nocapture readonly %C_matrix, 
    float* noalias nocapture readonly %D_vector,
    float* noalias nocapture readonly %delta_vector,
    float* noalias nocapture readonly %x_input,
    float* noalias nocapture %h_state,
    float* noalias nocapture writeonly %y_output,
    i32 %d_model,
    i32 %d_state
) #0 {
entry:
  %d_model_i64 = zext i32 %d_model to i64
  %d_state_i64 = zext i32 %d_state to i64
  %vector_lanes = i64 8
  %d_model_vec = and i64 %d_model_i64, -8  ; Round down to multiple of 8

  br label %model_vector_loop

model_vector_loop:
  %i_vec = phi i64 [ 0, %entry ], [ %i_vec_next, %model_vector_loop_body ]
  %i_vec_cmp = icmp ult i64 %i_vec, %d_model_vec
  br i1 %i_vec_cmp, label %model_vector_loop_body, label %model_scalar_remainder

model_vector_loop_body:
  ; Load 8 delta values
  %delta_vec_ptr = getelementptr inbounds float, float* %delta_vector, i64 %i_vec
  %delta_vec_ptr_cast = bitcast float* %delta_vec_ptr to <8 x float>*
  %delta_vec = load <8 x float>, <8 x float>* %delta_vec_ptr_cast, align 4, !tbaa !4

  ; Load 8 x input values  
  %x_vec_ptr = getelementptr inbounds float, float* %x_input, i64 %i_vec
  %x_vec_ptr_cast = bitcast float* %x_vec_ptr to <8 x float>*
  %x_vec = load <8 x float>, <8 x float>* %x_vec_ptr_cast, align 4, !tbaa !4

  ; Load 8 D values
  %d_vec_ptr = getelementptr inbounds float, float* %D_vector, i64 %i_vec
  %d_vec_ptr_cast = bitcast float* %d_vec_ptr to <8 x float>*
  %d_vec = load <8 x float>, <8 x float>* %d_vec_ptr_cast, align 4, !tbaa !4

  %ones_vec = <float 1.0, float 1.0, float 1.0, float 1.0, float 1.0, float 1.0, float 1.0, float 1.0>
  %zeros_vec = <float 0.0, float 0.0, float 0.0, float 0.0, float 0.0, float 0.0, float 0.0, float 0.0>

  ; Initialize y accumulator with D * x contribution
  %y_vec_acc = fmul fast <8 x float> %d_vec, %x_vec

  br label %state_vector_loop

state_vector_loop:
  %j_vec = phi i64 [ 0, %model_vector_loop_body ], [ %j_vec_next, %state_vector_loop_body ]
  %j_vec_cmp = icmp ult i64 %j_vec, %d_state_i64
  br i1 %j_vec_cmp, label %state_vector_loop_body, label %state_vector_loop_end

state_vector_loop_body:
  ; Process 8 model dimensions in parallel
  %h_vec_acc = alloca <8 x float>, align 32
  store <8 x float> %zeros_vec, <8 x float>* %h_vec_acc, align 32

  ; For each of the 8 lanes, load matrix elements and compute
  %lane0_offset = add nuw i64 %j_vec, %state_offset_0
  %state_offset_0 = mul nuw i64 %i_vec, %d_state_i64

  ; Load A, B, C matrix elements for all 8 lanes
  ; This is a simplified version - actual implementation would need careful indexing

  %j_vec_next = add nuw i64 %j_vec, 1
  br label %state_vector_loop

state_vector_loop_end:
  ; Apply activation function
  %y_vec_activated = call fast <8 x float> @llvm.tanh.v8f32(<8 x float> %y_vec_acc)

  ; Store results
