require "complex"
require "math"

module JaideOptimizer
  EPSILON = 1e-8_f32

  class AdaptiveMomentum
    property beta1 : Float32
    property beta2 : Float32
    property learning_rate : Float32
    property eps : Float32
    property weight_decay : Float32
    property amsgrad : Bool
    property momentum_window : Int32

    @exp_avg : Hash(String, Array(Float32))
    @exp_avg_sq : Hash(String, Array(Float32))
    @max_exp_avg_sq : Hash(String, Array(Float32))
    @gradient_history : Hash(String, Array(Array(Float32)))
    @step_count : Hash(String, Int32)

    def initialize(@learning_rate = 0.001_f32, 
                   @beta1 = 0.9_f32, 
                   @beta2 = 0.999_f32,
                   @eps = 1e-8_f32,
                   @weight_decay = 0.0_f32,
                   @amsgrad = false,
                   @momentum_window = 10)
      @exp_avg = Hash(String, Array(Float32)).new
      @exp_avg_sq = Hash(String, Array(Float32)).new
      @max_exp_avg_sq = Hash(String, Array(Float32)).new
      @gradient_history = Hash(String, Array(Array(Float32))).new
      @step_count = Hash(String, Int32).new
    end

    def step(param_name : String, parameters : Array(Float32), gradients : Array(Float32))
      raise ArgumentError.new("Parameters and gradients must have same length") if parameters.size != gradients.size

      # Initialize state if first time
      unless @exp_avg.has_key?(param_name)
        @exp_avg[param_name] = Array(Float32).new(parameters.size, 0.0_f32)
        @exp_avg_sq[param_name] = Array(Float32).new(parameters.size, 0.0_f32)
        @max_exp_avg_sq[param_name] = Array(Float32).new(parameters.size, 0.0_f32) if @amsgrad
        @gradient_history[param_name] = Array(Array(Float32)).new(@momentum_window) { Array(Float32).new(parameters.size, 0.0_f32) }
        @step_count[param_name] = 0
      end

      @step_count[param_name] += 1
      step = @step_count[param_name]

      exp_avg = @exp_avg[param_name]
      exp_avg_sq = @exp_avg_sq[param_name]
      max_exp_avg_sq = @max_exp_avg_sq[param_name] if @amsgrad
      grad_hist = @gradient_history[param_name]

      # Update gradient history
      hist_idx = (step - 1) % @momentum_window
      grad_hist[hist_idx] = gradients.dup

      # Calculate adaptive beta1 based on gradient consistency
      adaptive_beta1 = @beta1
      if step > @momentum_window
        avg_past_grad = calculate_average_gradient(grad_hist)
        consistency = calculate_gradient_consistency(gradients, avg_past_grad)
        adaptive_beta1 = @beta1 * (1.0_f32 + 0.3_f32 * consistency)
        adaptive_beta1 = Math.min(adaptive_beta1, 0.999_f32)
      end

      # Apply weight decay if specified
      if @weight_decay > 0.0_f32
        parameters.map_with_index! { |param, i| param * (1.0_f32 - @learning_rate * @weight_decay) }
      end

      # Update biased first moment estimate
      exp_avg.map_with_index! { |avg, i| adaptive_beta1 * avg + (1.0_f32 - adaptive_beta1) * gradients[i] }

      # Update biased second raw moment estimate  
      exp_avg_sq.map_with_index! { |avg_sq, i| @beta2 * avg_sq + (1.0_f32 - @beta2) * (gradients[i] ** 2) }

      # Compute bias-corrected first moment estimate
      bias_correction1 = 1.0_f32 - (adaptive_beta1 ** step)
      bias_correction2 = 1.0_f32 - (@beta2 ** step)

      if @amsgrad
        # Maintains the maximum of all 2nd moment running avg. till now
        max_exp_avg_sq.map_with_index! { |max_avg, i| Math.max(max_avg, exp_avg_sq[i]) }

        # Use the max for normalizing running avg. of gradient
        denom = max_exp_avg_sq.map { |max_avg| Math.sqrt(max_avg / bias_correction2) + @eps }
      else
        denom = exp_avg_sq.map { |avg_sq| Math.sqrt(avg_sq / bias_correction2) + @eps }
      end

      step_size = @learning_rate / bias_correction1

      # Update parameters
      parameters.map_with_index! do |param, i|
        param - step_size * (exp_avg[i] / denom[i])
      end

      parameters
    end

    private def calculate_average_gradient(grad_history : Array(Array(Float32))) : Array(Float32)
      return Array(Float32).new if grad_history.empty?

      avg_grad = Array(Float32).new(grad_history[0].size, 0.0_f32)
      valid_count = 0

      grad_history.each do |hist_grad|
        next if hist_grad.all? { |g| g == 0.0_f32 }

        hist_grad.each_with_index do |grad, i|
          avg_grad[i] += grad
        end
        valid_count += 1
      end

      if valid_count > 0
        avg_grad.map! { |sum| sum / valid_count.to_f32 }
      end

      avg_grad
    end

    private def calculate_gradient_consistency(current_grad : Array(Float32), avg_grad : Array(Float32)) : Float32
      return 0.0_f32 if current_grad.size != avg_grad.size

      dot_product = current_grad.zip(avg_grad).sum { |curr, avg| curr * avg }
      current_norm = Math.sqrt(current_grad.sum { |g| g ** 2 })
      avg_norm = Math.sqrt(avg_grad.sum { |g| g ** 2 })

      return 0.0_f32 if current_norm < EPSILON || avg_norm < EPSILON

      cosine_sim = dot_product / (current_norm * avg_norm)
      Math.max(0.0_f32, cosine_sim)
    end
  end

  class StateMatrixRegularizer
    property spectral_radius_target : Float32
    property regularization_strength : Float32

    def initialize(@spectral_radius_target = 0.99_f32, @regularization_strength = 0.01_f32)
    end

    def compute_spectral_regularization(matrix : Array(Array(Float32))) : Array(Array(Float32))
      rows = matrix.size
      cols = matrix[0].size
      regularization = Array(Array(Float32)).new(rows) { Array(Float32).new(cols, 0.0_f32) }

      # Approximate spectral radius using Gershgorin circle theorem
      matrix.each_with_index do |row, i|
        row_sum = row.sum { |val| val.abs }
        if row_sum > @spectral_radius_target
          overshoot = row_sum - @spectral_radius_target

          row.each_with_index do |val, j|
            reg_sign = val >= 0.0_f32 ? 1.0_f32 : -1.0_f32
            regularization[i][j] = @regularization_strength * reg_sign * overshoot
          end
        end
      end

      regularization
    end

    def apply_regularization(matrix : Array(Array(Float32)), regularization : Array(Array(Float32)), learning_rate : Float32)

