// app_V25.zig
const std = @import("std");
const print = std.debug.print;
const Allocator = std.mem.Allocator;
const ArrayList = std.ArrayList;
const HashMap = std.HashMap;
const math = std.math;
const mem = std.mem;
const os = std.os;
const c = std.c;

const JadeCore = @import("jade/core.zig");
const SynapseTokenizer = @import("tokenizer/synapse.zig");
const AethelredPipeline = @import("pipeline/aethelred.zig");
const ForgeHardware = @import("forge/hardware.zig");
const HGMOptimizer = @import("optimizer/hgm.zig");

pub const JAIDEV25System = struct {
    allocator: Allocator,
    core: *JadeCore.JadeSSM,
    tokenizer: *SynapseTokenizer.SynapseTokenizer,
    pipeline: *AethelredPipeline.Pipeline,
    hardware: *ForgeHardware.ForgeAccelerator,
    optimizer: *HGMOptimizer.HeuristicGradientMomentum,
    is_initialized: bool,
    model_parameters: HashMap([]const u8, []f32),
    training_data: ArrayList([]u8),
    inference_cache: HashMap(u32, []f32),
    security_context: SecurityContext,

    const SecurityContext = struct {
        encryption_key: [32]u8,
        session_token: [64]u8,
        access_level: u8,
        audit_log: ArrayList(AuditEntry),

        const AuditEntry = struct {
            timestamp: i64,
            operation: []const u8,
            user_id: u32,
            success: bool,
        };
    };

    const Self = @This();

    pub fn init(allocator: Allocator) !*Self {
        var system = try allocator.create(Self);

        // Initialize cryptographically secure random number generator
        var rng = std.rand.DefaultCsprng.init(blk: {
            var seed: u64 = undefined;
            try std.os.getrandom(std.mem.asBytes(&seed));
            break :blk seed;
        });

        system.* = Self{
            .allocator = allocator,
            .core = undefined,
            .tokenizer = undefined,
            .pipeline = undefined,
            .hardware = undefined,
            .optimizer = undefined,
            .is_initialized = false,
            .model_parameters = HashMap([]const u8, []f32).init(allocator),
            .training_data = ArrayList([]u8).init(allocator),
            .inference_cache = HashMap(u32, []f32).init(allocator),
            .security_context = SecurityContext{
                .encryption_key = undefined,
                .session_token = undefined,
                .access_level = 0,
                .audit_log = ArrayList(SecurityContext.AuditEntry).init(allocator),
            },
        };

        // Generate secure encryption keys
        try std.os.getrandom(&system.security_context.encryption_key);
        try std.os.getrandom(&system.security_context.session_token);

        // Initialize components with error handling
        system.core = JadeCore.JadeSSM.init(allocator, 8192, 256, 2048) catch |err| {
            print("Failed to initialize JadeSSM core: {}\n", .{err});
            return err;
        };

        system.tokenizer = SynapseTokenizer.SynapseTokenizer.init(allocator) catch |err| {
            print("Failed to initialize Synapse tokenizer: {}\n", .{err});
            return err;
        };

        system.pipeline = AethelredPipeline.Pipeline.init(allocator) catch |err| {
            print("Failed to initialize Aethelred pipeline: {}\n", .{err});
            return err;
        };

        system.hardware = ForgeHardware.ForgeAccelerator.init(allocator) catch |err| {
            print("Failed to initialize Forge hardware: {}\n", .{err});
            return err;
        };

        system.optimizer = HGMOptimizer.HeuristicGradientMomentum.init(allocator, 0.001, .{0.9, 0.999}) catch |err| {
            print("Failed to initialize HGM optimizer: {}\n", .{err});
            return err;
        };

        // Load pre-trained model parameters
        try system.loadModelParameters();

        system.is_initialized = true;
        try system.auditLog("system_init", 0, true);

        print("JAIDE V25 system initialized successfully\n");
        return system;
    }

    pub fn deinit(self: *Self) void {
        if (self.is_initialized) {
            self.auditLog("system_shutdown", 0, true) catch {};

            // Clear sensitive data
            mem.set(u8, &self.security_context.encryption_key, 0);
            mem.set(u8, &self.security_context.session_token, 0);

            // Free components
            self.core.deinit();
            self.tokenizer.deinit();
            self.pipeline.deinit();
            self.hardware.deinit();
            self.optimizer.deinit();

            // Free collections
            var param_iter = self.model_parameters.iterator();
            while (param_iter.next()) |entry| {
                self.allocator.free(entry.key_ptr.*);
                self.allocator.free(entry.value_ptr.*);
            }
            self.model_parameters.deinit();

            for (self.training_data.items) |data| {
                self.allocator.free(data);
            }
            self.training_data.deinit();

            var cache_iter = self.inference_cache.iterator();
            while (cache_iter.next()) |entry| {
                self.allocator.free(entry.value_ptr.*);
            }
            self.inference_cache.deinit();

            for (self.security_context.audit_log.items) |entry| {
                self.allocator.free(entry.operation);
            }
            self.security_context.audit_log.deinit();
        }
        self.allocator.destroy(self);
    }

    fn loadModelParameters(self: *Self) !void {
        const param_file = "models/jade_v25_base.bin";
        const file = std.fs.cwd().openFile(param_file, .{}) catch |err| {
            if (err == error.FileNotFound) {
                print("Model file not found, initializing with random parameters\n");
                try self.initializeRandomParameters();
                return;
            }
            return err;
        };
        defer file.close();

        const file_size = try file.getEndPos();
        const buffer = try self.allocator.alloc(u8, file_size);
        defer self.allocator.free(buffer);

        _ = try file.readAll(buffer);

        // Parse binary model format
        var offset: usize = 0;
        while (offset < buffer.len) {
            if (offset + 4 > buffer.len) break;

            const name_len = mem.readIntLittle(u32, buffer[offset..offset+4]);
            offset += 4;

            if (offset + name_len > buffer.len) break;
            const param_name = try self.allocator.dupe(u8, buffer[offset..offset+name_len]);
            offset += name_len;

            if (offset + 4 > buffer.len) break;
            const param_size = mem.readIntLittle(u32, buffer[offset..offset+4]);
            offset += 4;

            if (offset + param_size * 4 > buffer.len) break;
            var param_data = try self.allocator.alloc(f32, param_size);

            for (0..param_size) |i| {
                param_data[i] = @bitCast(mem.readIntLittle(u32, buffer[offset..offset+4]));
                offset += 4;
            }

            try self.model_parameters.put(param_name, param_data);
        }

        print("Loaded {} model parameters\n", .{self.model_parameters.count()});
    }

    fn initializeRandomParameters(self: *Self) !void {
        var rng = std.rand.DefaultPrng.init(@intCast(std.time.timestamp()));
        const random = rng.random();

        const layer_configs = [_]struct { name: []const u8, size: usize }{
            .{ .name = "embedding.weight", .size = 50257 * 8192 },
            .{ .name = "transformer.A_matrix", .size = 8192 * 256 },
            .{ .name = "transformer.B_matrix", .size = 8192 * 256 },
            .{ .name = "transformer.C_matrix", .size = 8192 * 256 },
            .{ .name = "transformer.D_vector", .size = 8192 },
            .{ .name = "lm_head.weight", .size = 8192 * 50257 },
        };

        for (layer_configs) |config| {
            const param_name = try self.allocator.dupe(u8, config.name);
            var param_data = try self.allocator.alloc(f32, config.size);

            const scale = @sqrt(2.0 / @as(f32, @floatFromInt(config.size)));
            for (param_data) |*param| {
                param.* = random.floatNorm(f32) * scale;
            }

            try self.model_parameters.put(param_name, param_data);
        }

        print("Initialized {} random model parameters\n", .{self.model_parameters.count()});
    }

    fn auditLog(self: *Self, operation: []const u8, user_id: u32, success: bool) !void {
        const entry = SecurityContext.AuditEntry{
            .timestamp = std.time.timestamp(),
            .operation = try self.allocator.dupe(u8, operation),
            .user_id = user_id,
            .success = success,
        };
        try self.security_context.audit_log.append(entry);

        // Limit audit log size
        if (self.security_context.audit_log.items.len > 10000) {
            const old_entry = self.security_context.audit_log.orderedRemove(0);
            self.allocator.free(old_entry.operation);
        }
    }

    pub fn runInference(self: *Self, prompt: []const u8, response_ptr: *[*:0]u8) i32 {
        if (!self.is_initialized) return -1;

        self.auditLog("inference_start", 0, true) catch return -1;

        // Hash prompt for caching
        var hasher = std.hash.Wyhash.init(0);
        hasher.update(prompt);
        const prompt_hash = @as(u32, @truncate(hasher.final()));

        // Check cache first
        if (self.inference_cache.get(prompt_hash)) |cached_result| {
            const response_text = self.tokenizer.decode(cached_result) catch return -2;
            response_ptr.* = @ptrCast(response_text.ptr);
            self.auditLog("inference_cached", 0, true) catch {};
            return 0;
        }

        // Tokenize input
        const tokens = self.tokenizer.encode(prompt) catch return -2;
        defer self.allocator.free(tokens);

        // Run forward pass through Jade SSM
        const embeddings = self.getEmbeddings(tokens) catch return -3;
        defer self.allocator.free(embeddings);

        const output_embeddings = self.core.forward(embeddings) catch return -4;
        defer self.allocator.free(output_embeddings);

        // Convert to logits and sample
        const output_tokens = self.sampleFromLogits(output_embeddings) catch return -5;
        defer self.allocator.free(output_tokens);

        // Cache result
        const cached_tokens = self.allocator.dupe(u32, output_tokens) catch return -6;
        self.inference_cache.put(prompt_hash, cached_tokens) catch {};

        // Decode to text
        const response_text = self.tokenizer.decode(output_tokens) catch return -7;
        response_ptr.* = @ptrCast(response_text.ptr);

        self.auditLog("inference_complete", 0, true) catch {};
        return 0;
    }

    fn getEmbeddings(self: *Self, tokens: []const u32) ![]f32 {
        const embedding_weights = self.model_parameters.get("embedding.weight") orelse return error.EmbeddingNotFound;
        const d_model = 8192;

        var embeddings = try self.allocator.alloc(f32, tokens.len * d_model);

        for (tokens, 0..) |token, i| {
            const token_offset = (token % 50257) * d_model;
            const embed_offset = i * d_model;

            @memcpy(embeddings[embed_offset..embed_offset + d_model], 
                   embedding_weights[token_offset..token_offset + d_model]);
        }

        return embeddings;
    }

    fn sampleFromLogits(self: *Self, embeddings: []const f32) ![]u32 {
        const lm_head_weights = self.model_parameters.get("lm_head.weight") orelse return error.LMHeadNotFound;
        const d_model = 8192;
        const vocab_size = 50257;
        const seq_len = embeddings.len / d_model;

        var output_tokens = try self.allocator.alloc(u32, seq_len);
        var rng = std.rand.DefaultPrng.init(@intCast(std.time.timestamp()));
        const random = rng.random();

        for (0..seq_len) |i| {
            const embed_offset = i * d_model;
            const input_embed = embeddings[embed_offset..embed_offset + d_model];

            // Compute logits: logits = input_embed @ lm_head_weights.T
            var logits = try self.allocator.alloc(f32, vocab_size);
            defer self.allocator.free(logits);

            for (0..vocab_size) |v| {
                var logit: f32 = 0.0;
                const weight_offset = v * d_model;
                const vocab_weights = lm_head_weights[weight_offset..weight_offset + d_model];

                for (0..d_model) |d| {
                    logit += input_embed[d] * vocab_weights[d];
                }
                logits[v] = logit;
            }

            // Apply softmax and sample
            var max_logit: f32 = logits[0];
            for (logits[1..]) |logit| {
                max_logit = @max(max_logit, logit);
            }

            var sum_exp: f32 = 0.0;
            for (logits) |*logit| {
                logit.* = @exp(logit.* - max_logit);
                sum_exp += logit.*;
            }

            for (logits) |*logit| {
                logit.* /= sum_exp;
            }

            // Multinomial sampling
            const r = random.float(f32);
            var cumsum: f32 = 0.0;
            for (logits, 0..) |prob, token| {
                cumsum += prob;
                if (r <= cumsum) {
                    output_tokens[i] = @intCast(token);
                    break;
                }
            }
        }

        return output_tokens;
    }

    pub fn runDistributedTraining(self: *Self, dataset_path: [*:0]const u8) bool {
        if (!self.is_initialized) return false;

        self.auditLog("training_start", 0, true) catch return false;

        const path = mem.span(dataset_path);
        const success = self.pipeline.processDataset(path) catch |err| {
            print("Training failed: {}\n", .{err});
            self.auditLog("training_failed", 0, false) catch {};
            return false;
        };

        if (success) {
            self.auditLog("training_complete", 0, true) catch {};
        }

        return success;
    }

    pub fn saveModel(self: *Self, path: []const u8) !void {
        const file = try std.fs.cwd().createFile(path, .{});
        defer file.close();

        var param_iter = self.model_parameters.iterator();
        while (param_iter.next()) |entry| {
            const name = entry.key_ptr.*;
            const params = entry.value_ptr.*;

            // Write name length and name
            try file.writeIntLittle(u32, @intCast(name.len));
            try file.writeAll(name);

            // Write parameter count and parameters
            try file.writeIntLittle(u32, @intCast(params.len));
            for (params) |param| {
                try file.writeIntLittle(u32, @bitCast(param));
            }
        }

        try self.auditLog("model_saved", 0, true);
        print("Model saved to {s}\n", .{path});
    }

    pub fn getSystemStats(self: *Self) ![]u8 {
        var stats = ArrayList(u8).init(self.allocator);
        defer stats.deinit();

        const writer = stats.writer();
        try writer.print("JAIDE V25 System Statistics:\n");
        try writer.print("- Model Parameters: {}\n", .{self.model_parameters.count()});
        try writer.print("- Training Examples: {}\n", .{self.training_data.items.len});
        try writer.print("- Cache Entries: {}\n", .{self.inference_cache.count()});
        try writer.print("- Audit Log Entries: {}\n", .{self.security_context.audit_log.items.len});
        try writer.print("- Memory Usage: {} MB\n", .{self.getMemoryUsage() / 1024 / 1024});

        return try stats.toOwnedSlice();
    }

    fn getMemoryUsage(self: *Self) usize {
        var total: usize = 0;

        var param_iter = self.model_parameters.iterator();
        while (param_iter.next()) |entry| {
            total += entry.key_ptr.len;
            total += entry.value_ptr.len * @sizeOf(f32);
        }

        for (self.training_data.items) |data| {
            total += data.len;
        }

        var cache_iter = self.inference_cache.iterator();
        while (cache_iter.next()) |entry| {
            total += entry.value_ptr.len * @sizeOf(u32);
        }

        return total;
    }
};

// FFI exports for Python interface
export fn jaide_v25_system_create() ?*JAIDEV25System {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    const allocator = gpa.allocator();
    return JAIDEV25System.init(allocator) catch |err| {
        print("System creation failed: {}\n", .{err});
        return null;
    };
}

export fn jaide_v25_system_destroy(system: *JAIDEV25System) void {
    system.deinit();
}

export fn jaide_v25_run_inference(system: *JAIDEV25System, prompt: [*:0]const u8, response: *[*:0]u8) i32 {
    const prompt_slice = mem.span(prompt);
    return system.runInference(prompt_slice, response);
}

export fn jaide_v25_run_distributed_training(system: *JAIDEV25System, dataset_path: [*:0]const u8) bool {
    return system.runDistributedTraining(dataset_path);
}

export fn jaide_v25_free_string(str: [*:0]u8) void {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    const allocator = gpa.allocator();
    allocator.free(mem.span(str));
}

export fn jaide_v25_save_model(system: *JAIDEV25System, path: [*:0]const u8) bool {
    const path_slice = mem.span(path);
    system.saveModel(path_slice) catch return false;
    return true;
}

export fn jaide_v25_get_stats(system: *JAIDEV25System, stats_ptr: *[*:0]u8) bool {
    const stats = system.getSystemStats() catch return false;
    stats_ptr.* = @ptrCast(stats.ptr);
    return true;
}

// jade/core.zig
const std = @import("std");
const math = std.math;
const Allocator = std.mem.Allocator;
const ArrayList = std.ArrayList;

pub const JadeSSM = struct {
    allocator: Allocator,
    d_model: u32,
    d_state: u32,
    seq_len: u32,
    A_matrix: []f32,
    B_matrix: []f32,
    C_matrix: []f32,
    D_matrix: []f32,
    delta_proj_weights: []f32,
    delta_proj_bias: []f32,
    x_proj_weights: []f32,
    x_proj_bias: []f32,
    out_proj_weights: []f32,
    out_proj_bias: []f32,
    layer_norm_weights: []f32,
    layer_norm_bias: []f32,
    hidden_state: []f32,
    intermediate_buffer: []f32,
    output_buffer: []f32,
    activation_cache: []f32,
    gradient_buffer: []f32,
    training_mode: bool,

    const Self = @This();

    pub fn init(allocator: Allocator, d_model: u32, d_state: u32, seq_len: u32) !*Self {
        var self = try allocator.create(Self);

        const matrix_size = d_model * d_state;
        const proj_size = d_model * d_model;
        const hidden_size = d_model * d_state;
        const buffer_size = seq_len * d_model;

        self.* = Self{
            .allocator = allocator,
            .d_model = d_model,
            .d_state = d_state,
            .seq_len = seq_len,
            .A_matrix = try allocator.alloc(f32, matrix_size),
            .B_matrix = try allocator.alloc(f32, matrix_size),
            .C_matrix = try allocator.alloc(f32, matrix_size),
            .D_matrix = try allocator.alloc(f32, d_model),
            .delta_proj_weights = try allocator.alloc(f32, proj_size),
            .delta_proj_bias = try allocator.alloc(f32, d_model),
            .x_proj_weights = try allocator.alloc(f32, proj_size),
            .x_proj_bias = try allocator.alloc(f32, d_model),
            .out_proj_weights = try allocator.alloc(f32, proj_size),
            .out_proj_bias = try allocator.alloc(f32, d_model),
            .layer_norm_weights = try allocator.alloc(f32, d_model),
            .layer_norm_bias = try allocator.alloc(f32, d_model),
            .hidden_state = try allocator.alloc(f32, hidden_size),
            .intermediate_buffer = try allocator.alloc(f32, buffer_size),
            .output_buffer = try allocator.alloc(f32, buffer_size),
            .activation_cache = try allocator.alloc(f32, buffer_size * 3),
            .gradient_buffer = try allocator.alloc(f32, matrix_size * 4),
            .training_mode = false,
        };

        try self.initializeParameters();
        return self;
    }

    pub fn deinit(self: *Self) void {
        self.allocator.free(self.A_matrix);
        self.allocator.free(self.B_matrix);
        self.allocator.free(self.C_matrix);
        self.allocator.free(self.D_matrix);
        self.allocator.free(self.delta_proj_weights);
        self.allocator.free(self.delta_proj_bias);
        self.allocator.free(self.x_proj_weights);
        self.allocator.free(self.x_proj_bias);
        self.allocator.free(self.out_proj_weights);
        self.allocator.free(self.out_proj_bias);
        self.allocator.free(self.layer_norm_weights);
        self.allocator.free(self.layer_norm_bias);
        self.allocator.free(self.hidden_state);
        self.allocator.free(self.intermediate_buffer);
        self.allocator.free(self.output_buffer);
        self.allocator.free(self.activation_cache);
        self.allocator.free(self.gradient_buffer);
        self.allocator.destroy(self);
    }

    fn initializeParameters(self: *Self) !void {
        var rng = std.rand.DefaultPrng.init(@intCast(std.time.timestamp()));
        const random = rng.random();

        // Initialize A matrix with stable eigenvalues
        const a_scale = 0.1;
        for (self.A_matrix) |*val| {
            val.* = random.floatNorm(f32) * a_scale;
        }

        // Make A matrix diagonally dominant for stability
        for (0..self.d_model) |i| {
            for (0..self.d_state) |j| {
                if (i == j and j < self.d_model) {
                    const idx = i * self.d_state + j;
                    self.A_matrix[idx] = -0.5 + random.float(f32) * 0.3;
                }
            }
        }

        // Initialize B and C matrices
        const bc_scale = @sqrt(2.0 / @as(f32, @floatFromInt(self.d_state)));
        for (self.B_matrix) |*val| {
            val.* = random.floatNorm(f32) * bc_scale;
        }
        for (self.C_matrix) |*val| {
            val.* = random.floatNorm(f32) * bc_scale;
        }

        // Initialize D matrix (skip connections)
        for (self.D_matrix) |*val| {
            val.* = random.floatNorm(f32) * 0.1;
        }

        // Initialize projection layers
        const proj_scale = @sqrt(2.0 / @as(f32, @floatFromInt(self.d_model)));
        for (self.delta_proj_weights) |*val| {
            val.* = random.floatNorm(f32) * proj_scale;
        }
        for (self.x_proj_weights) |*val| {
            val.* = random.floatNorm(f32) * proj_scale;
        }
        for (self.out_proj_weights) |*val| {
            val.* = random.floatNorm(f32) * proj_scale;
        }

        // Initialize biases to zero
        @memset(self.delta_proj_bias, 0.0);
        @memset(self.x_proj_bias, 0.0);
        @memset(self.out_proj_bias, 0.0);

        // Initialize layer norm parameters
        for (self.layer_norm_weights) |*val| {
            val.* = 1.0;
        }
        @memset(self.layer_norm_bias, 0.0);

        // Initialize hidden state
        @memset(self.hidden_state, 0.0);
    }

    pub fn forward(self: *Self, input_embeddings: []const f32) ![]f32 {
        const batch_size = input_embeddings.len / self.d_model;

        if (batch_size == 0) return error.InvalidInput;

        // Ensure we have enough buffer space
        if (self.output_buffer.len < batch_size * self.d_model) {
            return error.BufferTooSmall;
        }

        // Process each token in sequence
        for (0..batch_size) |t| {
            const input_offset = t * self.d_model;
            const output_offset = t * self.d_model;

            const x_t = input_embeddings[input_offset..input_offset + self.d_model];
            const y_t = self.output_buffer[output_offset..output_offset + self.d_model];

            try self.forwardStep(x_t, y_t, t);
        }

        return self.output_buffer[0..batch_size * self.d_model];
    }

    fn forwardStep(self: *Self, x_t: []const f32, y_t: []f32, step: usize) !void {
        // Apply layer normalization to input
        var normalized_x = try self.allocator.alloc(f32, self.d_model);
        defer self.allocator.free(normalized_x);

        self.layerNorm(x_t, normalized_x, self.layer_norm_weights, self.layer_norm_bias);

        // Compute delta projection: delta = softplus(W_delta @ x + b_delta)
        var delta = try self.allocator.alloc(f32, self.d_model);
        defer self.allocator.free(delta);

        self.linearTransform(normalized_x, delta, self.delta_proj_weights, self.delta_proj_bias);
        for (delta) |*d| {
            d.* = math.log1p(@exp(d.*)); // softplus activation
        }

        // Compute input projection: x_proj = W_x @ x + b_x
        var x_proj = try self.allocator.alloc(f32, self.d_model);
        defer self.allocator.free(x_proj);

        self.linearTransform(normalized_x, x_proj, self.x_proj_weights, self.x_proj_bias);

        // SSM computation for each model dimension
        for (0..self.d_model) |i| {
            var h_new: f32 = 0.0;

            // Compute new hidden state: h_new = A_bar * h_prev + B_bar * x_proj
            for (0..self.d_state) |j| {
                const matrix_idx = i * self.d_state + j;
                const h_idx = i * self.d_state + j;

                // Discretize A and B matrices
                const A_bar = 1.0 + delta[i] * self.A_matrix[matrix_idx];
                const B_bar = delta[i] * self.B_matrix[matrix_idx];

                h_new += A_bar * self.hidden_state[h_idx] + B_bar * x_proj[i];

                // Update hidden state
                self.hidden_state[h_idx] = h_new;
            }

            // Compute output: y = C @ h + D * x
            var output: f32 = self.D_matrix[i] * x_proj[i];
            for (0..self.d_state) |j| {
                const matrix_idx = i * self.d_state + j;
                const h_idx = i * self.d_state + j;
                output += self.C_matrix[matrix_idx] * self.hidden_state[h_idx];
            }

            // Store intermediate result
            self.intermediate_buffer[step * self.d_model + i] = output;
        }

        // Apply output projection
        self.linearTransform(self.intermediate_buffer[step * self.d_model..step * self.d_model + self.d_model], 
                           y_t, self.out_proj_weights, self.out_proj_bias);

        // Apply activation function (SiLU/Swish)
        for (y_t) |*y| {
            y.* = y.* / (1.0 + @exp(-y.*));
        }

        // Cache activations for backward pass if in training mode
        if (self.training_mode) {
            const cache_offset = step * self.d_model * 3;
            @memcpy(self.activation_cache[cache_offset..cache_offset + self.d_model], normalized_x);
            @memcpy(self.activation_cache[cache_offset + self.d_model..cache_offset + 2 * self.d_model], x_proj);
            @memcpy(self.activation_cache[cache_offset + 2 * self.d_model..cache_offset + 3 * self.d_model], y_t);
        }
    }

    fn layerNorm(self: *Self, input: []const f32, output: []f32, weight: []const f32, bias: []const f32) void {
        // Compute mean
        var mean: f32 = 0.0;
        for (input) |x| {
            mean += x;
        }
        mean /= @as(f32, @floatFromInt(input.len));

        // Compute variance
        var variance: f32 = 0.0;
        for (input) |x| {
            const diff = x - mean;
            variance += diff * diff;
        }
        variance /= @as(f32, @floatFromInt(input.len));

        // Normalize and scale
        const eps: f32 = 1e-5;
        const inv_std = 1.0 / @sqrt(variance + eps);

        for (input, output, weight, bias) |x, *y, w, b| {
            y.* = (x - mean) * inv_std * w + b;
        }
    }

    fn linearTransform(self: *Self, input: []const f32, output: []f32, weight: []const f32, bias: []const f32) void {
        const input_dim = input.len;
        const output_dim = output.len;

        for (0..output_dim) |i| {
            var sum: f32 = bias[i];
            for (0..input_dim) |j| {
                sum += weight[i * input_dim + j] * input[j];
            }
            output[i] = sum;
        }
    }

    pub fn backward(self: *Self, grad_output: []const f32) ![]f32 {
        if (!self.training_mode) return error.NotInTrainingMode;

        const batch_size = grad_output.len / self.d_model;
        var grad_input = try self.allocator.alloc(f32, grad_output.len);

        // Initialize gradient buffers
        @memset(self.gradient_buffer, 0.0);

        // Backward pass through time
        var t: isize = @intCast(batch_size - 1);
        while (t >= 0) : (t -= 1) {
            const step = @as(usize, @intCast(t));
            const grad_offset = step * self.d_model;
            const cache_offset = step * self.d_model * 3;

            const grad_y = grad_output[grad_offset..grad_offset + self.d_model];
            const cached_norm_x = self.activation_cache[cache_offset..cache_offset + self.d_model];
            const cached_x_proj = self.activation_cache[cache_offset + self.d_model..cache_offset + 2 * self.d_model];
            const cached_y = self.activation_cache[cache_offset + 2 * self.d_model..cache_offset + 3 * self.d_model];

            try self.backwardStep(grad_y, cached_norm_x, cached_x_proj, cached_y, 
                                grad_input[grad_offset..grad_offset + self.d_model], step);
        }

        return grad_input;
    }

    fn backwardStep(self: *Self, grad_y: []const f32, cached_norm_x: []const f32, 
                   cached_x_proj: []const f32, cached_y: []const f32, 
                   grad_x: []f32, step: usize) !void {
        // Gradient of SiLU activation
        var grad_pre_activation = try self.allocator.alloc(f32, self.d_model);
        defer self.allocator.free(grad_pre_activation);

        for (grad_y, cached_y, grad_pre_activation) |gy, y, *gpa| {
            const sigmoid = 1.0 / (1.0 + @exp(-y));
            gpa.* = gy * sigmoid * (1.0 + y * (1.0 - sigmoid));
        }

        // Gradient through output projection
        var grad_intermediate = try self.allocator.alloc(f32, self.d_model);
        defer self.allocator.free(grad_intermediate);

        // grad_intermediate = W_out^T @ grad_pre_activation
        for (0..self.d_model) |i| {
            var sum: f32 = 0.0;
            for (0..self.d_model) |j| {
                sum += self.out_proj_weights[j * self.d_model + i] * grad_pre_activation[j];
            }
            grad_intermediate[i] = sum;
        }

        // Accumulate gradients for output projection weights and bias
        for (0..self.d_model) |i| {
            for (0..self.d_model) |j| {
                const weight_idx = i * self.d_model + j;
                const intermediate_val = self.intermediate_buffer[step * self.d_model + j];
                // Accumulate in gradient buffer (simplified indexing)
                self.gradient_buffer[weight_idx] += grad_pre_activation[i] * intermediate_val;
            }
        }

        // Gradient through SSM computation
        var grad_x_proj = try self.allocator.alloc(f32, self.d_model);
        defer self.allocator.free(grad_x_proj);
        @memset(grad_x_proj, 0.0);

        var grad_h = try self.allocator.alloc(f32, self.d_model * self.d_state);
        defer self.allocator.free(grad_h);

        // Compute gradients w.r.t. hidden states and inputs
        for (0..self.d_model) |i| {
            const grad_output_i = grad_intermediate[i];

            // Gradient w.r.t. D matrix
            grad_x_proj[i] += self.D_matrix[i] * grad_output_i;

            // Gradient w.r.t. C matrix and hidden states
            for (0..self.d_state) |j| {
                const matrix_idx = i * self.d_state + j;
                const h_idx = i * self.d_state + j;

                grad_h[h_idx] += self.C_matrix[matrix_idx] * grad_output_i;
            }
        }

        // Gradient through input projection
        for (0..self.d_model) |i| {
            var sum: f32 = 0.0;
            for (0..self.d_model) |j| {
                sum += self.x_proj_weights[j * self.d_model + i] * grad_x_proj[j];
            }
            grad_x[i] = sum;
        }
    }

    pub fn setTrainingMode(self: *Self, training: bool) void {
        self.training_mode = training;
    }

    pub fn resetHiddenState(self: *Self) void {
        @memset(self.hidden_state, 0.0);
    }

    pub fn getParameters(self: *Self) [][]f32 {
        return &[_][]f32{
            self.A_matrix,
            self.B_matrix,
            self.C_matrix,
            self.D_matrix,
            self.delta_proj_weights,
            self.delta_proj_bias,
            self.x_proj_weights,
            self.x_proj_bias,
            self.out_proj_weights,
            self.out_proj_bias,
            self.layer_norm_weights,
            self.layer_norm_bias,
        };
    }

    pub fn getGradients(self: *Self) []f32 {
        return self.gradient_buffer;
    }

    pub fn clipGradients(self: *Self, max_norm: f32) void {
        var total_norm: f32 = 0.0;

        for (self.gradient_buffer) |grad| {
            total_norm += grad * grad;
        }

        total_norm = @sqrt(total_norm);

        if (total_norm > max_norm) {
            const scale = max_norm / total_norm;
            for (self.gradient_buffer) |*grad| {
                grad.* *= scale;
            }
        }
    }
};

// tokenizer/synapse.zig
const std = @import("std");
const Allocator = std.mem.Allocator;
const ArrayList = std.ArrayList;
const HashMap = std.HashMap;
const StringHashMap = std.StringHashMap;

pub const SynapseTokenizer = struct {
    allocator: Allocator,
    vocab: StringHashMap(u32),
    reverse_vocab: HashMap(u32, []const u8),
    merge_rules: ArrayList(MergeRule),
    special_tokens: StringHashMap(u32),
    next_token_id: u32,
    vocab_size: u32,
    bpe_ranks: HashMap([2]u32, u32),
    dropout_prob: f32,
    training_mode: bool,

    const MergeRule = struct {
        pair: [2]u32,
        new_token: u32,
        frequency: u32,
    };

    const Self = @This();

    pub fn init(allocator: Allocator) !*Self {
        var self = try allocator.create(Self);

        self.* = Self{
            .allocator = allocator,
            .vocab = StringHashMap(u32).init(allocator),
            .reverse_vocab = HashMap(u32, []const u8).init(allocator),
            .merge_rules = ArrayList(MergeRule).init(allocator),
            .special_tokens = StringHashMap(u32).init(allocator),
            .next_token_id = 256,
            .vocab_size = 50257,
            .bpe_ranks = HashMap([2]u32, u32).init(allocator),
            .dropout_prob = 0.0,
            .training_mode = false,
        };

        try self.initializeBaseVocab();
        try self.loadPretrainedMerges();
        return self;
    }

    pub fn deinit(self: *Self) void {
        // Free vocabulary strings
        var vocab_iter = self.vocab.iterator();
        while (vocab_iter.next()) |entry| {
            self.allocator.free(entry.key_ptr.*);
        }
        self.vocab.deinit();

        var reverse_iter = self.reverse_vocab.iterator();
        while (reverse_iter.next()) |entry| {
            self.allocator.free(entry.value_ptr.*);
        }
        self.reverse_vocab.deinit();

        self.merge_rules.deinit();

        var special_iter = self.special_tokens.iterator();
        while (special_iter.next()) |entry| {
            self.allocator.free(entry.key_ptr.*);
        }
        self.special_tokens.deinit();

        self.bpe_ranks.deinit();
        self.allocator.destroy(self);
    }

    fn initializeBaseVocab(self: *Self) !void {
        // Initialize byte-level vocabulary (0-255)
        for (0..256) |i| {
            const byte_str = try self.allocator.alloc(u8, 1);
            byte_str[0] = @intCast(i);
            const token_id = @as(u32, @intCast(i));

            try self.vocab.put(byte_str, token_id);
            try self.reverse_vocab.put(token_id, byte_str);
        }

        // Add special tokens
        const special_token_list = [_][]const u8{
            "<|endoftext|>",
            "<|startoftext|>", 
            "<|padding|>",
            "<|unknown|>",
            "<|mask|>",
        };

        for (special_token_list) |token| {
            const token_copy = try self.allocator.dupe(u8, token);
            try self.special_tokens.put(token_copy, self.next_token_id);
            try self.vocab.put(token_copy, self.next_token_id);
            try self.reverse_vocab.put(self.next_token_id, token_copy);
            self.next_token_id += 1;
        }

        std.log.info("Initialized base vocabulary with {} tokens", .{self.vocab.count()});
    }

    fn loadPretrainedMerges(self: *Self) !void {
        // Load GPT-2 style BPE merges
        const merges_file = "tokenizer/merges.txt";
        const file = std.fs.cwd().openFile(merges_file, .{}) catch |err| {
            if (err == error.FileNotFound) {
                std.log.warn("Merges file not found, starting with empty merge table");
                return;
            }
            return err;
        };
        defer file.close();

        const content = try file.readToEndAlloc(self.allocator, 100 * 1024 * 1024); // 100MB max
        defer self.allocator.free(content);

        var lines = std.mem.split(u8, content, "\n");
        var rank: u32 = 0;

        while (lines.next()) |line| {
            const trimmed = std.mem.trim(u8, line, " \t\r\n");
            if (trimmed.len == 0 or trimmed[0] == '#') continue;

            var parts = std.mem.split(u8, trimmed, " ");
            const first = parts.next() orelse continue;
            const second = parts.next() orelse continue;

            const first_token = self.vocab.get(first) orelse continue;
            const second_token = self.vocab.get(second) orelse continue;

            const pair = [2]u32{ first_token, second_token };
            try self.bpe_ranks.put(pair, rank);

            // Create merge rule
            const merge_result = try std.fmt.allocPrint(self.allocator, "{s}{s}", .{ first, second });
            try self.vocab.put(merge_result, self.next_token_id);
            try self.reverse_vocab.put(self.next_token_id, merge_result);

            const rule = MergeRule{
                .pair = pair,
                .new_token = self.next_token_id,
                .frequency = 0,
            };
            try self.merge_rules.append(rule);

            self.next_token_id += 1;
            rank += 1;

            if (self.next_token_id >= self.vocab_size) break;
        }

        std.log.info("Loaded {} BPE merge rules", .{self.merge_rules.items.len});
    }

    pub fn encode(self: *Self, text: []const u8) ![]u32 {
        if (text.len == 0) {
            return try self.allocator.alloc(u32, 0);
        }

        // Preprocessing: normalize whitespace and handle special characters
        var normalized = try self.normalizeText(text);
        defer self.allocator.free(normalized);

        // Tokenize into words/subwords
        var words = try self.splitIntoWords(normalized);
        defer {
            for (words.items) |word| {
                self.allocator.free(word);
            }
            words.deinit();
        }

        var all_tokens = ArrayList(u32).init(self.allocator);
        defer all_tokens.deinit();

        // Process each word
        for (words.items) |word| {
            var word_tokens = try self.encodeWord(word);
            defer self.allocator.free(word_tokens);

            try all_tokens.appendSlice(word_tokens);
        }

        return try all_tokens.toOwnedSlice();
    }

    fn normalizeText(self: *Self, text: []const u8) ![]u8 {
        var result = ArrayList(u8).init(self.allocator);
        defer result.deinit();

        var i: usize = 0;
        while (i < text.len) {
            const c = text[i];

            // Handle UTF-8 sequences
            if (c < 128) {
                // ASCII character
                if (std.ascii.isControl(c)) {
                    if (c == '\n' or c == '\r' or c == '\t') {
                        try result.append(' ');
                    }
                    // Skip other control characters
                } else {
                    try result.append(c);
                }
                i += 1;
            } else {
                // Multi-byte UTF-8 character
                const utf8_len = std.unicode.utf8ByteSequenceLength(c) catch {
                    i += 1;
                    continue;
                };

                if (i + utf8_len > text.len) break;

                const codepoint = std.unicode.utf8Decode(text[i..i+utf8_len]) catch {
                    i += 1;
                    continue;
                };

                // Convert to bytes for BPE processing
                var utf8_bytes: [4]u8 = undefined;
                const byte_len = std.unicode.utf8Encode(codepoint, &utf8_bytes) catch {
                    i += utf8_len;
                    continue;
                };

                try result.appendSlice(utf8_bytes[0..byte_len]);
                i += utf8_len;
            }
        }

        return try result.toOwnedSlice();
    }

    fn splitIntoWords(self: *Self, text: []const u8) !ArrayList([]u8) {
        var words = ArrayList([]u8).init(self.allocator);
        var current_word = ArrayList(u8).init(self.allocator);
        defer current_word.deinit();

        for (text) |c| {
            if (std.ascii.isWhitespace(c)) {
                if (current_word.items.len > 0) {
                    try words.append(try current_word.toOwnedSlice());
                    current_word.clearRetainingCapacity();
                }
            } else {
                try current_word.append(c);
            }
        }

        if (current_word.items.len > 0) {
            try words.append(try current_word.toOwnedSlice());
        }

        return words;
    }

    fn encodeWord(self: *Self, word: []const u8) ![]u32 {
        if (word.len == 0) {
            return try self.allocator.alloc(u32, 0);
        }

        // Convert word to initial token sequence (byte-level)
        var tokens = ArrayList(u32).init(self.allocator);
        defer tokens.deinit();

        for (word) |byte| {
            try tokens.append(byte);
        }

        // Apply BPE merges
        while (true) {
            const merge_pair = self.findBestMerge(tokens.items) orelse break;

            // Apply dropout during training
            var rng = std.rand.DefaultPrng.init(@intCast(std.time.timestamp()));
            if (self.training_mode and rng.random().float(f32) < self.dropout_prob) {
                break;
            }

            self.applyMerge(&tokens, merge_pair);
        }

        return try tokens.toOwnedSlice();
    }

    fn findBestMerge(self: *Self, tokens: []const u32) ?[2]u32 {
        if (tokens.len < 2) return null;

        var best_pair: ?[2]u32 = null;
        var best_rank: u32 = std.math.maxInt(u32);

        for (tokens[0..tokens.len-1], 1..) |first_token, i| {
            const second_token = tokens[i];
            const pair = [2]u32{ first_token, second_token };

            if (self.bpe_ranks.get(pair)) |rank| {
                if (rank < best_rank) {
                    best_rank = rank;
                    best_pair = pair;
                }
            }
        }

        return best_pair;
    }

    fn applyMerge(self: *Self, tokens: *ArrayList(u32), pair: [2]u32) void {
        var i: usize = 0;
        while (i < tokens.items.len - 1) {
            if (tokens.items[i] == pair[0] and tokens.items[i + 1] == pair[1]) {
                // Find the merged token ID
                var merge_token: u32 = 0;
                for (self.merge_rules.items) |rule| {
                    if (rule.pair[0] == pair[0] and rule.pair[1] == pair[1]) {
                        merge_token = rule.new_token;
                        break;
                    }
                }

                if (merge_token != 0) {
                    tokens.items[i] = merge_token;
                    _ = tokens.orderedRemove(i + 1);
                }
            } else {
                i += 1;
            }
        }
    }

    pub fn decode(self: *Self, tokens: []const u32) ![]u8 {
        var result = ArrayList(u8).init(self.allocator);
        defer result.deinit();

        for (tokens) |token| {
            if (self.reverse_vocab.get(token)) |token_str| {
                try result.appendSlice(token_str);
            } else {
                // Handle unknown tokens
                const unknown_str = self.special_tokens.get("<|unknown|>") orelse 3; // fallback
                if (self.reverse_vocab.get(unknown_str)) |unk_str| {
                    try result.appendSlice(unk_str);
                }
            }
        }

        return try result.toOwnedSlice();
    }

    pub fn trainBPE(self: *Self, corpus: []const []const u8, num_merges: u32) !void {
        std.log.info("Training BPE with {} merges on {} documents", .{ num_merges, corpus.len });

        // Count pair frequencies across the corpus
        var pair_counts = HashMap([2]u32, u32).init(self.allocator);
        defer pair_counts.deinit();

        // Process corpus and count pairs
        for (corpus) |document| {
            var word_tokens = try self.encodeWord(document);
            defer self.allocator.free(word_tokens);

            for (word_tokens[0..word_tokens.len-1], 1..) |first, i| {
                const second = word_tokens[i];
                const pair = [2]u32{ first, second };

                const count = pair_counts.get(pair) orelse 0;
                try pair_counts.put(pair, count + 1);
            }
        }

        // Perform merges
        for (0..num_merges) |merge_idx| {
            // Find most frequent pair
            var best_pair: [2]u32 = undefined;
            var best_count: u32 = 0;

            var iter = pair_counts.iterator();
            while (iter.next()) |entry| {
                if (entry.value_ptr.* > best_count) {
                    best_count = entry.value_ptr.*;
                    best_pair = entry.key_ptr.*;
                }
            }

            if (best_count < 2) break; // Stop if no frequent pairs

            // Create new merge rule
            const merge_rule = MergeRule{
                .pair = best_pair,
                .new_token = self.next_token_id,
                .frequency = best_count,
            };

            try self.merge_rules.append(merge_rule);
            try self.bpe_ranks.put(best_pair, @intCast(merge_idx));

            // Create vocabulary entry for merged token
            const first_str = self.reverse_vocab.get(best_pair[0]) orelse "<?>";  
            const second_str = self.reverse_vocab.get(best_pair[1]) orelse "<?>";
            const merged_str = try std.fmt.allocPrint(self.allocator, "{s}{s}", .{ first_str, second_str });

            try self.vocab.put(merged_str, self.next_token_id);
            try self.reverse_vocab.put(self.next_token_id, merged_str);

            self.next_token_id += 1;

            // Update pair counts by removing old pairs and adding new ones
            _ = pair_counts.remove(best_pair);

            if (merge_idx % 1000 == 0) {
                std.log.info("Completed {} merges", .{merge_idx + 1});
            }
        }

        std.log.info("BPE training completed with {} merge rules", .{self.merge_rules.items.len});
    }

    pub fn setTrainingMode(self: *Self, training: bool) void {
        self.training_mode = training;
    }

    pub fn setDropoutProb(self: *Self, prob: f32) void {
        self.dropout_prob = std.math.clamp(prob, 0.0, 1.0);
    }

    pub fn getVocabSize(self: *Self) u32 {
        return @intCast(self.vocab.count());
    }

    pub fn saveVocab(self: *Self, path: []const u8) !void {
        const file = try std.fs.cwd().createFile(path, .{});
        defer file.close();

        const writer = file.writer();

        // Write vocab size
        try writer.writeIntLittle(u32, @intCast(self.vocab.count()));

        // Write vocabulary
        var vocab_iter = self.vocab.iterator();
        while (vocab_iter.next()) |entry| {
            const token_str = entry.key_ptr.*;
            const token_id = entry.value_ptr.*;

            try writer.writeIntLittle(u32, @intCast(token_str.len));
            try writer.writeAll(token_str);
            try writer.writeIntLittle(u32, token_id);
        }

        // Write merge rules
        try writer.writeIntLittle(u32, @intCast(self.merge_rules.items.len));
        for (self.merge_rules.items) |rule| {
            try writer.writeIntLittle(u32, rule.pair[0]);
            try writer.writeIntLittle(u32, rule.pair[1]);
            try writer.writeIntLittle(u32, rule.new_token);
            try writer.writeIntLittle(u32, rule.frequency);
        }

        std.log.info("Vocabulary saved to {s}", .{path});
    }

    pub fn loadVocab(self: *Self, path: []const u8) !void {
        const file = try std.fs.cwd().openFile(path, .{});
        defer file.close();

        const reader = file.reader();

        // Clear existing vocabulary
        self.vocab.clearAndFree();
        self.reverse_vocab.clearAndFree();
        self.merge_rules.clearAndFree();
        self.bpe_ranks.clearAndFree();

        // Read vocab size
        const vocab_size = try reader.readIntLittle(u32);

        // Read vocabulary
        for (0..vocab_size) |_| {
            const str_len = try reader.readIntLittle(u32);
            const token_str = try self.allocator.alloc(u8, str_len);
            try reader.readNoEof(token_str);

            const token_id = try reader.readIntLittle(u32);

            try self.vocab.put(token_str, token_id);
            try self.reverse_vocab.put(token_id, token_str);
        }

        // Read merge rules
        const num_merges = try reader.readIntLittle(u32);
        for (0..num_merges) |i| {
            const first = try reader.readIntLittle(u32);
            const second = try reader.readIntLittle(u32);
            const new_token = try reader.readIntLittle(u32);
            const frequency = try reader.readIntLittle(u32);

            const rule = MergeRule{
                .pair = [2]u32{ first, second },
                .new_token = new_token,
                .frequency = frequency,
            };

            try self.merge_rules.append(rule);
            try self.bpe_ranks.put(rule.pair, @intCast(i));
        }

        // Update next token ID
        var max_token_id: u32 = 0;
        var vocab_iter = self.vocab.iterator();
        while (vocab_iter.next()) |entry| {
            max_token_id = @max(max_token_id, entry.value_ptr.*);
        }
        self.next_token_id = max_token_id + 1;

        std.log.info("Vocabulary loaded from {s} with {} tokens and {} merges", 
                   .{ path, self.vocab.count(), self.merge_rules.items.len });
    }
};

// pipeline/aethelred.zig
const std = @import("std");
const Allocator = std.mem.Allocator;
const ArrayList = std.ArrayList;
const Thread = std.Thread;
const Mutex = std.Thread.Mutex;
const Condition = std.Thread.Condition;
const AtomicBool = std.atomic.Atomic(bool);
const AtomicUsize = std.atomic.Atomic(usize);

pub const Pipeline = struct {
    allocator: Allocator,
    worker_threads: []Thread,
    task_queue: TaskQueue,
    result_queue: ResultQueue,
    worker_pool: WorkerPool,
    data_processor: DataProcessor,
    batch_manager: BatchManager,
    metrics: PipelineMetrics,
    shutdown_signal: AtomicBool,
    is_running: bool,

    const TaskQueue = struct {
        tasks: ArrayList(ProcessingTask),
        mutex: Mutex,
        condition: Condition,
        max_size: usize,

        const ProcessingTask = struct {
            id: u64,
            data: []u8,
            priority: Priority,
            timestamp: i64,
            processing_params: ProcessingParams,

            const Priority = enum(u8) {
                low = 0,
                normal = 1,
                high = 2,
                critical = 3,
            };

            const ProcessingParams = struct {
                batch_size: u32,
                sequence_length: u32,
                attention_mask: ?[]bool,
                tokenizer_config: ?TokenizerConfig,

                const TokenizerConfig = struct {
                    vocab_size: u32,
                    max_length: u32,
                    padding_token: u32,
                    eos_token: u32,
                };
            };
        };

        fn init(allocator: Allocator, max_size: usize) TaskQueue {
            return TaskQueue{
                .tasks = ArrayList(ProcessingTask).init(allocator),
                .mutex = Mutex{},
                .condition = Condition{},
                .max_size = max_size,
            };
        }

        fn deinit(self: *TaskQueue) void {
            for (self.tasks.items) |task| {
                self.tasks.allocator.free(task.data);
                if (task.processing_params.attention_mask) |mask| {
                    self.tasks.allocator.free(mask);
                }
            }
            self.tasks.deinit();
        }

        fn enqueue(self: *TaskQueue, task: ProcessingTask) !void {
            self.mutex.lock();
            defer self.mutex.unlock();

            if (self.tasks.items.len >= self.max_size) {
                return error.QueueFull;
            }

            // Insert task in priority order
            var insert_pos = self.tasks.items.len;
            for (self.tasks.items, 0..) |existing_task, i| {
                if (@intFromEnum(task.priority) > @intFromEnum(existing_task.priority)) {
                    insert_pos = i;
                    break;
                }
            }

            try self.tasks.insert(insert_pos, task);
            self.condition.signal();
        }

        fn dequeue(self: *TaskQueue, timeout_ms: u64) ?ProcessingTask {
            self.mutex.lock();
            defer self.mutex.unlock();

            const timeout_ns = timeout_ms * std.time.ns_per_ms;
            const deadline = std.time.nanoTimestamp() + @as(i64, @intCast(timeout_ns));

            while (self.tasks.items.len == 0) {
                const now = std.time.nanoTimestamp();
                if (now >= deadline) return null;

                const remaining_ns = @as(u64, @intCast(deadline - now));
                self.condition.timedWait(&self.mutex, remaining_ns) catch return null;
            }

            return self.tasks.orderedRemove(0);
        }

        fn size(self: *TaskQueue) usize {
            self.mutex.lock();
            defer self.mutex.unlock();
            return self.tasks.items.len;
        }
    };

    const ResultQueue = struct {
        results: ArrayList(ProcessingResult),
        mutex: Mutex,
        condition: Condition,

        const ProcessingResult = struct {
            task_id: u64,
            success: bool,
            output_data: ?[]u8,
            error_message: ?[]u8,
            processing_time_ns: u64,
            memory_used: usize,
        };

        fn init(allocator: Allocator) ResultQueue {
            return ResultQueue{
                .results = ArrayList(ProcessingResult).init(allocator),
                .mutex = Mutex{},
                .condition = Condition{},
            };
        }

        fn deinit(self: *ResultQueue) void {
            for (self.results.items) |result| {
                if (result.output_data) |data| {
                    self.results.allocator.free(data);
                }
                if (result.error_message) |msg| {
                    self.results.allocator.free(msg);
                }
            }
            self.results.deinit();
        }

        fn enqueue(self: *ResultQueue, result: ProcessingResult) !void {
            self.mutex.lock();
            defer self.mutex.unlock();

            try self.results.append(result);
            self.condition.signal();
        }

        fn dequeue(self: *ResultQueue) ?ProcessingResult {
            self.mutex.lock();
            defer self.mutex.unlock();

            if (self.results.items.len == 0) return null;
            return self.results.orderedRemove(0);
        }
    };

    const WorkerPool = struct {
        workers: []Worker,
        active_workers: AtomicUsize,

        const Worker = struct {
            id: u32,
            thread_handle: ?Thread,
            task_processor: TaskProcessor,
            local_allocator: Allocator,
            statistics: WorkerStats,

            const TaskProcessor = struct {
                tokenizer: ?*@import("../tokenizer/synapse.zig").SynapseTokenizer,
                model_core: ?*@import("../jade/core.zig").JadeSSM,
                batch_buffer: []u8,
                temp_buffer: []u8,

                fn init(allocator: Allocator) !TaskProcessor {
                    return TaskProcessor{
                        .tokenizer = null,
                        .model_core = null,
                        .batch_buffer = try allocator.alloc(u8, 1024 * 1024), // 1MB
                        .temp_buffer = try allocator.alloc(u8, 512 * 1024),   // 512KB
                    };
                }

                fn deinit(self: *TaskProcessor, allocator: Allocator) void {
                    allocator.free(self.batch_buffer);
                    allocator.free(self.temp_buffer);
                }
            };

            const WorkerStats = struct {
                tasks_processed: u64,
                total_processing_time_ns: u64,
                errors_encountered: u64,
                bytes_processed: u64,
                last_activity_timestamp: i64,
            };
        };

        fn init(allocator: Allocator, num_workers: u32) !WorkerPool {
            var workers = try allocator.alloc(Worker, num_workers);

            for (workers, 0..) |*worker, i| {
                worker.* = Worker{
                    .id = @intCast(i),
                    .thread_handle = null,
                    .task_processor = try Worker.TaskProcessor.init(allocator),
                    .local_allocator = allocator,
                    .statistics = Worker.WorkerStats{
                        .tasks_processed = 0,
                        .total_processing_time_ns = 0,
                        .errors_encountered = 0,
                        .bytes_processed = 0,
                        .last_activity_timestamp = std.time.timestamp(),
                    },
                };
            }

            return WorkerPool{
                .workers = workers,
                .active_workers = AtomicUsize.init(0),
            };
        }

        fn deinit(self: *WorkerPool, allocator: Allocator) void {
            for (self.workers) |*worker| {
                worker.task_processor.deinit(allocator);
            }
            allocator.free(self.workers);
        }
    };

    const DataProcessor = struct {
        preprocessing_config: PreprocessingConfig,
        postprocessing_config: PostprocessingConfig,
        validation_rules: ArrayList(ValidationRule),

        const PreprocessingConfig = struct {
            normalize_whitespace: bool,
            remove_control_chars: bool,
            max_sequence_length: u32,
            truncation_strategy: TruncationStrategy,
            padding_strategy: PaddingStrategy,

            const TruncationStrategy = enum {
                longest_first,
                only_first,
                only_second,
                do_not_truncate,
            };

            const PaddingStrategy = enum {
                longest,
                max_length,
                do_not_pad,
            };
        };

        const PostprocessingConfig = struct {
            decode_special_tokens: bool,
            clean_up_tokenization_spaces: bool,
            skip_special_tokens: bool,
        };

        const ValidationRule = struct {
            rule_type: RuleType,
            parameters: []const u8,

            const RuleType = enum {
                min_length,
                max_length,
                contains_pattern,
                excludes_pattern,
                encoding_validation,
            };
        };

        fn init(allocator: Allocator) DataProcessor {
            return DataProcessor{
                .preprocessing_config = PreprocessingConfig{
                    .normalize_whitespace = true,
                    .remove_control_chars = true,
                    .max_sequence_length = 2048,
                    .truncation_strategy = .longest_first,
                    .padding_strategy = .longest,
                },
                .postprocessing_config = PostprocessingConfig{
                    .decode_special_tokens = false,
                    .clean_up_tokenization_spaces = true,
                    .skip_special_tokens = true,
                },
                .validation_rules = ArrayList(ValidationRule).init(allocator),
            };
        }

        fn deinit(self: *DataProcessor) void {
            for (self.validation_rules.items) |rule| {
                self.validation_rules.allocator.free(rule.parameters);
            }
            self.validation_rules.deinit();
        }

        fn processData(self: *DataProcessor, input_data: []const u8, allocator: Allocator) ![]u8 {
            // Validate input
            for (self.validation_rules.items) |rule| {
                try self.applyValidationRule(rule, input_data);
            }

            // Preprocess
            var processed_data = try self.preprocess(input_data, allocator);

            return processed_data;
        }

        fn preprocess(self: *DataProcessor, data: []const u8, allocator: Allocator) ![]u8 {
            var result = ArrayList(u8).init(allocator);
            defer result.deinit();

            for (data) |byte| {
                if (self.preprocessing_config.remove_control_chars and std.ascii.isControl(byte)) {
                    if (byte == '\n' or byte == '\r' or byte == '\t') {
                        if (self.preprocessing_config.normalize_whitespace) {
                            try result.append(' ');
                        } else {
                            try result.append(byte);
                        }
                    }
                    // Skip other control characters
                } else {
                    try result.append(byte);
                }
            }

            // Apply sequence length limits
            if (result.items.len > self.preprocessing_config.max_sequence_length) {
                switch (self.preprocessing_config.truncation_strategy) {
                    .longest_first, .only_first => {
                        result.shrinkRetainingCapacity(self.preprocessing_config.max_sequence_length);
                    },
                    .do_not_truncate => {
                        return error.SequenceTooLong;
                    },
                    else => {
                        // Handle other truncation strategies
                    }
                }
            }

            return try result.toOwnedSlice();
        }

        fn applyValidationRule(self: *DataProcessor, rule: ValidationRule, data: []const u8) !void {
            switch (rule.rule_type) {
                .min_length => {
                    const min_len = std.mem.readIntLittle(u32, rule.parameters[0..4]);
                    if (data.len < min_len) return error.DataTooShort;
                },
                .max_length => {
                    const max_len = std.mem.readIntLittle(u32, rule.parameters[0..4]);
                    if (data.len > max_len) return error.DataTooLong;
                },
                .contains_pattern => {
                    if (std.mem.indexOf(u8, data, rule.parameters) == null) {
                        return error.RequiredPatternNotFound;
                    }
                },
                .excludes_pattern => {
                    if (std.mem.indexOf(u8, data, rule.parameters) != null) {
                        return error.ForbiddenPatternFound;
                    }
                },
                .encoding_validation => {
                    if (!std.unicode.utf8ValidateSlice(data)) {
                        return error.InvalidUtf8Encoding;
                    }
                },
            }
        }
    };

    const BatchManager = struct {
        batch_size: u32,
        max_batch_wait_ms: u64,
        current_batch: ArrayList(TaskQueue.ProcessingTask),
        batch_timer: ?std.time.Timer,

        fn init(allocator: Allocator, batch_size: u32, max_wait_ms: u64) BatchManager {
            return BatchManager{
                .batch_size = batch_size,
                .max_batch_wait_ms = max_wait_ms,
                .current_batch = ArrayList(TaskQueue.ProcessingTask).init(allocator),
                .batch_timer = null,
            };
        }

        fn deinit(self: *BatchManager) void {
            self.current_batch.deinit();
        }

        fn shouldProcessBatch(self: *BatchManager) bool {
            if (self.current_batch.items.len >= self.batch_size) return true;

            if (self.batch_timer) |*timer| {
                const elapsed_ms = timer.read() / std.time.ns_per_ms;
                return elapsed_ms >= self.max_batch_wait_ms;
            }

            return false;
        }

        fn addTask(self: *BatchManager, task: TaskQueue.ProcessingTask) !void {
            if (self.current_batch.items.len == 0) {
                self.batch_timer = std.time.Timer.start() catch null;
            }

            try self.current_batch.append(task);
        }

        fn extractBatch(self: *BatchManager) []TaskQueue.ProcessingTask {
            defer {
                self.current_batch.clearRetainingCapacity();
                self.batch_timer = null;
            }
            return self.current_batch.toOwnedSlice() catch &[_]TaskQueue.ProcessingTask{};
        }
    };

    const PipelineMetrics = struct {
        tasks_queued: AtomicUsize,
        tasks_completed: AtomicUsize,
        tasks_failed: AtomicUsize,
        total_processing_time_ns: AtomicUsize,
        total_bytes_processed: AtomicUsize,
        queue_high_water_mark: AtomicUsize,
        avg_task_latency_ns: AtomicUsize,
        throughput_tasks_per_second: f64,
        last_metrics_update: i64,

        fn init() PipelineMetrics {
            return PipelineMetrics{
                .tasks_queued = AtomicUsize.init(0),
                .tasks_completed = AtomicUsize.init(0),
                .tasks_failed = AtomicUsize.init(0),
                .total_processing_time_ns = AtomicUsize.init(0),
                .total_bytes_processed = AtomicUsize.init(0),
                .queue_high_water_mark = AtomicUsize.init(0),
                .avg_task_latency_ns = AtomicUsize.init(0),
                .throughput_tasks_per_second = 0.0,
                .last_metrics_update = std.time.timestamp(),
            };
        }

        fn updateMetrics(self: *PipelineMetrics) void {
            const now = std.time.timestamp();
            const time_diff = now - self.last_metrics_update;

            if (time_diff > 0) {
                const completed = self.tasks_completed.load(.Monotonic);
                self.throughput_tasks_per_second = @as(f64, @floatFromInt(completed)) / @as(f64, @floatFromInt(time_diff));

                const total_time = self.total_processing_time_ns.load(.Monotonic);
                if (completed > 0) {
                    self.avg_task_latency_ns.store(total_time / completed, .Monotonic);
                }

                self.last_metrics_update = now;
            }
        }
    };

    const Self = @This();

    pub fn init(allocator: Allocator) !*Self {
        const num_workers = @max(1, std.Thread.getCpuCount() catch 4);
        var pipeline = try allocator.create(Self);

        pipeline.* = Self{
            .allocator = allocator,
            .worker_threads = try allocator.alloc(Thread, num_workers),
            .task_queue = TaskQueue.init(allocator, 10000),
            .result_queue = ResultQueue.init(allocator),
            .worker_pool = try WorkerPool.init(allocator, @intCast(num_workers)),
            .data_processor = DataProcessor.init(allocator),
            .batch_manager = BatchManager.init(allocator, 32, 100), // 32 tasks or 100ms timeout
            .metrics = PipelineMetrics.init(),
            .shutdown_signal = AtomicBool.init(false),
            .is_running = false,
        };

        try pipeline.startWorkers();
        pipeline.is_running = true;

        std.log.info("Aethelred pipeline initialized with {} workers", .{num_workers});
        return pipeline;
    }

    pub fn deinit(self: *Self) void {
        if (self.is_running) {
            self.shutdown();
        }

        self.task_queue.deinit();
        self.result_queue.deinit();
        self.worker_pool.deinit(self.allocator);
        self.data_processor.deinit();
        self.batch_manager.deinit();
        self.allocator.free(self.worker_threads);
        self.allocator.destroy(self);
    }

    fn startWorkers(self: *Self) !void {
        for (self.worker_threads, 0..) |*thread, i| {
            thread.* = try Thread.spawn(.{}, workerMain, .{ self, @intCast(i) });
        }
    }

    fn workerMain(pipeline: *Pipeline, worker_id: u32) void {
        const worker = &pipeline.worker_pool.workers[worker_id];
        _ = pipeline.worker_pool.active_workers.fetchAdd(1, .Monotonic);
        defer _ = pipeline.worker_pool.active_workers.fetchSub(1, .Monotonic);

        std.log.info("Worker {} started", .{worker_id});

        while (!pipeline.shutdown_signal.load(.Monotonic)) {
            // Try to get a task
            if (pipeline.task_queue.dequeue(1000)) |task| { // 1 second timeout
                const start_time = std.time.nanoTimestamp();
                const result = pipeline.processTask(worker, task);
                const end_time = std.time.nanoTimestamp();

                // Update worker statistics
                worker.statistics.tasks_processed += 1;
                worker.statistics.total_processing_time_ns += @intCast(end_time - start_time);
                worker.statistics.bytes_processed += task.data.len;
                worker.statistics.last_activity_timestamp = std.time.timestamp();

                if (!result.success) {
                    worker.statistics.errors_encountered += 1;
                }

                // Queue the result
                pipeline.result_queue.enqueue(result) catch |err| {
                    std.log.err("Worker {}: Failed to enqueue result: {}", .{ worker_id, err });
                };

                // Update pipeline metrics
                _ = pipeline.metrics.tasks_completed.fetchAdd(1, .Monotonic);
                _ = pipeline.metrics.total_processing_time_ns.fetchAdd(@intCast(end_time - start_time), .Monotonic);
                _ = pipeline.metrics.total_bytes_processed.fetchAdd(task.data.len, .Monotonic);
            } else {
                // Timeout occurred, continue loop to check shutdown signal
                continue;
            }
        }

        std.log.info("Worker {} shutting down", .{worker_id});
    }

    fn processTask(self: *Self, worker: *WorkerPool.Worker, task: TaskQueue.ProcessingTask) ResultQueue.ProcessingResult {
        const start_time = std.time.nanoTimestamp();
        var memory_used: usize = 0;

        // Process the task data
        const processed_data = self.data_processor.processData(task.data, worker.local_allocator) catch |err| {
            const error_msg = std.fmt.allocPrint(worker.local_allocator, "Data processing failed: {}", .{err}) catch "Unknown error";
            return ResultQueue.ProcessingResult{
                .task_id = task.id,
                .success = false,
                .output_data = null,
                .error_message = error_msg,
                .processing_time_ns = @intCast(std.time.nanoTimestamp() - start_time),
                .memory_used = memory_used,
            };
        };

        memory_used += processed_data.len;

        // For now, just return the processed data as output
        // In a real implementation, this would involve model inference
        const output_data = worker.local_allocator.dupe(u8, processed_data) catch |err| {
            worker.local_allocator.free(processed_data);
            const error_msg = std.fmt.allocPrint(worker.local_allocator, "Output allocation failed: {}", .{err}) catch "Allocation error";
            return ResultQueue.ProcessingResult{
                .task_id = task.id,
                .success = false,
                .output_data = null,
                .error_message = error_msg,
                .processing_time_ns = @intCast(std.time.nanoTimestamp() - start_time),
                .memory_used = memory_used,
            };
        };

        worker.local_allocator.free(processed_data);
        memory_used += output_data.len;

        return ResultQueue.ProcessingResult{
            .task_id = task.id,
            .success = true,
            .output_data = output_data,
            .error_message = null,
            .processing_time_ns = @intCast(std.time.nanoTimestamp() - start_time),
            .memory_used = memory_used,
        };
    }

    pub fn processDataset(self: *Self, dataset_path: []const u8) !bool {
        if (!self.is_running) return false;

        std.log.info("Processing dataset: {s}", .{dataset_path});

        const file = std.fs.cwd().openFile(dataset_path, .{}) catch |err| {
            std.log.err("Failed to open dataset file: {}", .{err});
            return false;
        };
        defer file.close();

        const file_size = try file.getEndPos();
        if (file_size == 0) {
            std.log.warn("Dataset file is empty");
            return true;
        }

        const content = try self.allocator.alloc(u8, file_size);
        defer self.allocator.free(content);

        _ = try file.readAll(content);

        // Split content into chunks for processing
        const chunk_size = 4096; // 4KB chunks
        var task_id: u64 = 0;
        var tasks_submitted: usize = 0;

        var offset: usize = 0;
        while (offset < content.len) {
            const end_offset = @min(offset + chunk_size, content.len);
            const chunk = content[offset..end_offset];

            // Create a copy of the chunk for the task
            const chunk_copy = try self.allocator.dupe(u8, chunk);

            const task = TaskQueue.ProcessingTask{
                .id = task_id,
                .data = chunk_copy,
                .priority = .normal,
                .timestamp = std.time.timestamp(),
                .processing_params = TaskQueue.ProcessingTask.ProcessingParams{
                    .batch_size = 1,
                    .sequence_length = @intCast(chunk.len),
                    .attention_mask = null,
                    .tokenizer_config = null,
                },
            };

            self.task_queue.enqueue(task) catch |err| {
                std.log.err("Failed to enqueue task {}: {}", .{ task_id, err });
                self.allocator.free(chunk_copy);
                continue;
            };

            _ = self.metrics.tasks_queued.fetchAdd(1, .Monotonic);
            tasks_submitted += 1;
            task_id += 1;
            offset += chunk_size;
        }

        std.log.info("Submitted {} tasks for processing", .{tasks_submitted});

        // Wait for all tasks to complete
        var completed_tasks: usize = 0;
        const start_time = std.time.timestamp();
        const timeout_seconds: i64 = 300; // 5 minutes timeout

        while (completed_tasks < tasks_submitted) {
            if (std.time.timestamp() - start_time > timeout_seconds) {
                std.log.err("Dataset processing timed out after {} seconds", .{timeout_seconds});
                return false;
            }

            if (self.result_queue.dequeue()) |result| {
                completed_tasks += 1;

                if (!result.success) {
                    std.log.err("Task {} failed: {s}", .{ result.task_id, result.error_message orelse "Unknown error" });
                    _ = self.metrics.tasks_failed.fetchAdd(1, .Monotonic);
                }

                // Free result data
                if (result.output_data) |data| {
                    self.allocator.free(data);
                }
                if (result.error_message) |msg| {
                    self.allocator.free(msg);
                }

                if (completed_tasks % 100 == 0) {
                    std.log.info("Completed {}/{} tasks", .{ completed_tasks, tasks_submitted });
                }
            } else {
                // No result available, sleep briefly
                std.time.sleep(std.time.ns_per_ms * 10); // 10ms
            }
        }

        const end_time = std.time.timestamp();
        const processing_time = end_time - start_time;

        std.log.info("Dataset processing completed in {} seconds", .{processing_time});
        self.metrics.updateMetrics();

        return true;
    }

    pub fn submitTask(self: *Self, data: []const u8, priority: TaskQueue.ProcessingTask.Priority) !u64 {
        if (!self.is_running) return error.PipelineNotRunning;

        const task_id = @as(u64, @intCast(std.time.nanoTimestamp()));
        const data_copy = try self.allocator.dupe(u8, data);

        const task = TaskQueue.ProcessingTask{
            .id = task_id,
            .data = data_copy,
            .priority = priority,
            .timestamp = std.time.timestamp(),
            .processing_params = TaskQueue.ProcessingTask.ProcessingParams{
                .batch_size = 1,
                .sequence_length = @intCast(data.len),
                .attention_mask = null,
                .tokenizer_config = null,
            },
        };

        try self.task_queue.enqueue(task);
        _ = self.metrics.tasks_queued.fetchAdd(1, .Monotonic);

        // Update queue high water mark
        const current_queue_size = self.task_queue.size();
        var current_hwm = self.metrics.queue_high_water_mark.load(.Monotonic);
        while (current_queue_size > current_hwm) {
            current_hwm = self.metrics.queue_high_water_mark.compareAndSwap(
                current_hwm, current_queue_size, .Monotonic, .Monotonic
            ) orelse break;
        }

        return task_id;
    }

    pub fn getResult(self: *Self, task_id: u64, timeout_ms: u64) ?ResultQueue.ProcessingResult {
        const start_time = std.time.milliTimestamp();

        while ((std.time.milliTimestamp() - start_time) < timeout_ms) {
            if (self.result_queue.dequeue()) |result| {
                if (result.task_id == task_id) {
                    return result;
                } else {
                    // Put it back for other consumers (simplified)
                    self.result_queue.enqueue(result) catch {};
                }
            }

            std.time.sleep(std.time.ns_per_ms * 10); // 10ms
        }

        return null;
    }

    pub fn getMetrics(self: *Self) PipelineMetrics {
        self.metrics.updateMetrics();
        return self.metrics;
    }

    pub fn shutdown(self: *Self) void {
        if (!self.is_running) return;

        std.log.info("Shutting down Aethelred pipeline...");

        self.shutdown_signal.store(true, .Release);

        // Wait for all worker threads to finish
        for (self.worker_threads) |*thread| {
            thread.join();
        }

        self.is_running = false;
        std.log.info("Pipeline shutdown complete");
    }

    pub fn getStatus(self: *Self) []u8 {
        const metrics = self.getMetrics();

        return std.fmt.allocPrint(self.allocator,
            \\Aethelred Pipeline Status:
            \\- Running: {}
            \\- Active Workers: {}
            \\- Queue Size: {}
            \\- Queue High Water Mark: {}
            \\- Tasks Queued: {}
            \\- Tasks Completed: {}
            \\- Tasks Failed: {}
            \\- Average Latency: {d:.2f}ms
            \\- Throughput: {d:.2f} tasks/sec
            \\- Total Bytes Processed: {}
        , .{
            self.is_running,
            self.worker_pool.active_workers.load(.Monotonic),
            self.task_queue.size(),
            metrics.queue_high_water_mark.load(.Monotonic),
            metrics.tasks_queued.load(.Monotonic),
            metrics.tasks_completed.load(.Monotonic),
            metrics.tasks_failed.load(.Monotonic),
            @as(f64, @floatFromInt(metrics.avg_task_latency_ns.load(.Monotonic))) / 1_000_000.0,
            metrics.throughput_tasks_per_second,
            metrics.total_bytes_processed.load(.Monotonic),
        }) catch "Status unavailable";
    }
};

// forge/hardware.zig
const std = @import("std");
const Allocator = std.mem.Allocator;
const ArrayList = std.ArrayList;
const AtomicUsize = std.atomic.Atomic(usize);
const AtomicBool = std.atomic.Atomic(bool);

pub const ForgeAccelerator = struct {
    allocator: Allocator,
    compute_units: []ComputeUnit,
    memory_controller: MemoryController,
    instruction_cache: InstructionCache,
    register_file: RegisterFile,
    pipeline_controller: PipelineController,
    performance_counters: PerformanceCounters,
    is_initialized: bool,

    const ComputeUnit = struct {
        id: u32,
        vector_alu: VectorALU,
        matrix_multiplier: MatrixMultiplier,
        activation_unit: ActivationUnit,
        local_memory: []u8,
        state: ComputeUnitState,
        instruction_queue: ArrayList(Instruction),

        const VectorALU = struct {
            pipeline_stages: u8,
            vector_width: u32,
            supported_ops: SupportedOps,

            const SupportedOps = struct {
                add: bool,
                mul: bool,
                fma: bool,
                sqrt: bool,
                exp: bool,
                log: bool,
            };
        };

        const MatrixMultiplier = struct {
            tile_size: u32,
            accumulator_precision: u8,
            supports_mixed_precision: bool,
        };

        const ActivationUnit = struct {
            supports_relu: bool,
            supports_gelu: bool,
            supports_swish: bool,
            supports_tanh: bool,
            supports_sigmoid: bool,
        };

        const ComputeUnitState = enum {
            idle,
            busy,
            stalled,
            error,
        };

        const Instruction = struct {
            opcode: Opcode,
            src_regs: [3]u32,
            dst_reg: u32,
            immediate: u32,
            flags: InstructionFlags,

            const Opcode = enum(u8) {
                nop = 0x00,
                vadd = 0x01,
                vmul = 0x02,
                vfma = 0x03,
                mgemm = 0x04,
                load = 0x05,
                store = 0x06,
                activate = 0x07,
                ssm_step = 0x08,
                sync = 0x09,
                halt = 0x0A,
            };

            const InstructionFlags = struct {
                vector_mask: u32,
                precision: Precision,
                synchronous: bool,

                const Precision = enum(u2) {
                    fp16 = 0,
                    fp32 = 1,
                    int8 = 2,
                    int16 = 3,
                };
            };
        };
    };

    const MemoryController = struct {
        dram_banks: []DRAMBank,
        cache_hierarchy: CacheHierarchy,
        memory_map: MemoryMap,
        bandwidth_monitor: BandwidthMonitor,

        const DRAMBank = struct {
            base_address: u64,
            size: usize,
            data: []u8,
            access_latency_cycles: u32,
            bandwidth_gb_per_sec: f32,
        };

        const CacheHierarchy = struct {
            l1_cache: Cache,
            l2_cache: Cache,
            l3_cache: Cache,

            const Cache = struct {
                size: usize,
                line_size: u32,
                associativity: u32,
                data: []u8,
                tags: []CacheTag,
                replacement_policy: ReplacementPolicy,

                const CacheTag = struct {
                    valid: bool,
                    dirty: bool,
                    tag: u64,
                    lru_counter: u32,
                };

                const ReplacementPolicy = enum {
                    lru,
                    lfu,
                    random,
                };
            };
        };

        const MemoryMap = struct {
            regions: ArrayList(MemoryRegion),

            const MemoryRegion = struct {
                name: []const u8,
                base_address: u64,
                size: usize,
                permissions: Permissions,
                region_type: RegionType,

                const Permissions = struct {
                    read: bool,
                    write: bool,
                    execute: bool,
                };

                const RegionType = enum {
                    dram,
                    sram,
                    mmio,
                    reserved,
                };
            };
        };

        const BandwidthMonitor = struct {
            read_bytes_per_second: AtomicUsize,
            write_bytes_per_second: AtomicUsize,
            total_transactions: AtomicUsize,
            last_measurement_time: i64,
        };
    };

    const InstructionCache = struct {
        cache_lines: []CacheLine,
        program_counter: u64,
        instruction_buffer: []u32,
        prefetch_enabled: bool,

        const CacheLine = struct {
            valid: bool,
            tag: u32,
            instructions: [16]u32, // 16 instructions per line
        };
    };

    const RegisterFile = struct {
        vector_registers: []VectorRegister,
        scalar_registers: []u64,
        special_registers: SpecialRegisters,

        const VectorRegister = struct {
            data: []f32,
            size: u32,
            data_type: DataType,

            const DataType = enum {
                fp32,
                fp16,
                int32,
                int16,
                int8,
            };
        };

        const SpecialRegisters = struct {
            config_reg: u64,
            status_reg: u64,
            error_reg: u64,
            performance_counter_base: u64,
        };
    };

    const PipelineController = struct {
        fetch_stage: FetchStage,
        decode_stage: DecodeStage,
        execute_stage: ExecuteStage,
        writeback_stage: WritebackStage,
        pipeline_depth: u8,
        stall_cycles: AtomicUsize,

        const FetchStage = struct {
            pc: u64,
            instruction_word: u32,
            valid: bool,
        };

        const DecodeStage = struct {
            instruction: ComputeUnit.Instruction,
            operands_ready: bool,
            resource_available: bool,
        };

        const ExecuteStage = struct {
            alu_result: u64,
            memory_address: u64,
            execution_cycles: u8,
        };

        const WritebackStage = struct {
            result_data: []u8,
            destination_register: u32,
            write_enable: bool,
        };
    };

    const PerformanceCounters = struct {
        cycles: AtomicUsize,
        instructions_retired: AtomicUsize,
        cache_hits: AtomicUsize,
        cache_misses: AtomicUsize,
        memory_stalls: AtomicUsize,
        compute_utilization: f32,
        power_consumption_watts: f32,
        temperature_celsius: f32,
    };

    const Self = @This();

    pub fn init(allocator: Allocator) !*Self {
        var accelerator = try allocator.create(Self);

        // Initialize compute units
        const num_compute_units = 16;
        var compute_units = try allocator.alloc(ComputeUnit, num_compute_units);

        for (compute_units, 0..) |*cu, i| {
            cu.* = ComputeUnit{
                .id = @intCast(i),
                .vector_alu = ComputeUnit.VectorALU{
                    .pipeline_stages = 4,
                    .vector_width = 256, // 256-bit vectors
                    .supported_ops = ComputeUnit.VectorALU.SupportedOps{
                        .add = true,
                        .mul = true,
                        .fma = true,
                        .sqrt = true,
                        .exp = true,
                        .log = true,
                    },
                },
                .matrix_multiplier = ComputeUnit.MatrixMultiplier{
                    .tile_size = 16,
                    .accumulator_precision = 32,
                    .supports_mixed_precision = true,
                },
                .activation_unit = ComputeUnit.ActivationUnit{
                    .supports_relu = true,
                    .supports_gelu = true,
                    .supports_swish = true,
                    .supports_tanh = true,
                    .supports_sigmoid = true,
                },
                .local_memory = try allocator.alloc(u8, 64 * 1024), // 64KB per CU
                .state = .idle,
                .instruction_queue = ArrayList(ComputeUnit.Instruction).init(allocator),
            };
        }

        // Initialize memory controller
        const num_dram_banks = 8;
        var dram_banks = try allocator.alloc(MemoryController.DRAMBank, num_dram_banks);

        for (dram_banks, 0..) |*bank, i| {
            const bank_size = 1024 * 1024 * 1024; // 1GB per bank
            bank.* = MemoryController.DRAMBank{
                .base_address = i * bank_size,
